const HTML = "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"theme-color\" content=\"#2563eb\">\n<meta name=\"mobile-web-app-capable\" content=\"yes\">\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"default\">\n<meta name=\"apple-mobile-web-app-title\" content=\"工作台\">\n<title>聚合工作台</title>\n<link rel=\"icon\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop offset='0' stop-color='%232563eb'/%3E%3Cstop offset='1' stop-color='%234f46e5'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='24' height='24' rx='6' fill='url(%23g)'/%3E%3Cpath d='M7 7h4v4H7zM13 7h4v4h-4zM7 13h4v4H7zM13 13h4v4h-4z' fill='%23fff'/%3E%3C/svg%3E\">\n<script>\n/* 主题预应用：避免暗色用户首屏闪白 */\n(function(){\n  try{\n    var t = localStorage.getItem('wb_hub_theme') || 'auto';\n    var dark = t === 'dark' || (t === 'auto' && window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches);\n    if (dark) document.documentElement.setAttribute('data-theme', 'dark');\n  }catch(e){}\n})();\n</script>\n<script>\n/* =========================================================\n * ◆◆◆ 环境变量区 WB_ENV ◆◆◆\n * 部署前直接改这里 → 重新部署，即可对所有设备生效默认值。\n * 页面「设置」面板里的修改只影响本设备浏览器；\n * 想让文件里的配置重新覆盖设备本地值，用设置里的\n * 「应用页面内置配置」按钮。\n * ========================================================= */\nwindow.WB_ENV = {\n  BRAND: \"聚合工作台\",          // 工作台名称\n  DEMO_MODE: true,              // true=未接入 API 的服务显示演示数据\n  POLL_MINUTES: 0,              // 全局自动刷新间隔(分钟)，0=关闭\n  LOGIN: {                      // 登录门禁（前端口令级防护，防路人误入，非加密级安全）\n    USER: \"maoxinhe\",                                    // 登录账号\n    SALT: \"wb-hub-2026-v1\",                              // 哈希盐值\n    PASS_SHA256: \"12f0a1de9d4b255513f110f71a7be27f7dcc191e2a0d2f38d1ceb8052a7e050c\" // sha256(SALT+密码)\n  },\n  /* 云同步：把工作台配置与待办存到本仓库 data/state.json（GitHub Contents API）。\n     ⚠️ 同步 Token 不要写在这里！在页面「设置 → 云同步」中填写，仅存于各设备浏览器本地 */\n  SYNC: {\n    REPO: \"maoxinhe/service-hub\",   // GitHub 仓库（owner/name）\n    BRANCH: \"main\",                  // 分支\n    PATH: \"data/state.json\",         // 数据文件路径\n    AUTO: true                       // 默认开启自动同步（仍需在本设备填一次 Token）\n  },\n  /* 各服务 API 参数：URL=服务前端地址(跳转用) API=接口地址(返回JSON) AUTH=none|bearer|header */\n  SERVICES: {\n    downloads: { NAME: \"下载站\",       URL: \"\", API: \"\", AUTH: \"none\", TOKEN: \"\", HEADER: \"X-API-Key\" },\n    errors:    { NAME: \"错误报告分析\", URL: \"\", API: \"\", AUTH: \"none\", TOKEN: \"\", HEADER: \"X-API-Key\" },\n    tickets:   { NAME: \"工单系统\",     URL: \"\", API: \"\", AUTH: \"none\", TOKEN: \"\", HEADER: \"X-API-Key\" },\n    mods:      { NAME: \"模组更新平台\", URL: \"\", API: \"\", AUTH: \"none\", TOKEN: \"\", HEADER: \"X-API-Key\" },\n    blog:      { NAME: \"个人博客\",     URL: \"\", API: \"\", AUTH: \"none\", TOKEN: \"\", HEADER: \"X-API-Key\" },\n    wiki:      { NAME: \"Wiki\",         URL: \"https://my-wiki.catkinr-93f.workers.dev\", API: \"https://my-wiki.catkinr-93f.workers.dev/api/articles\", AUTH: \"none\", TOKEN: \"\", HEADER: \"X-API-Key\" }\n  }\n};\n</script>\n<style>\n  :root{\n    --primary:#2563eb; --primary2:#4f46e5; --primary-weak:#eff6ff;\n    --grad:linear-gradient(135deg,#2563eb,#4f46e5);\n    --bg:#eef2f8; --card:#ffffff; --line:#e5eaf2; --line2:#eef1f7;\n    --text:#0f172a; --text2:#64748b; --text3:#94a3b8;\n    --red:#dc2626; --red-bg:#fef2f2; --red-t:#dc2626;\n    --orange:#ea580c; --orange-bg:#fff7ed;\n    --green:#16a34a; --green-bg:#f0fdf4;\n    --blue-bg:#eff6ff;\n    --radius:16px; --radius-s:11px;\n    --shadow:0 1px 2px rgba(15,23,42,.04), 0 6px 20px rgba(15,23,42,.06);\n    --shadow-lift:0 4px 10px rgba(15,23,42,.06), 0 14px 34px rgba(37,99,235,.13);\n    --glass:rgba(255,255,255,.86);\n  }\n  html[data-theme=\"dark\"]{\n    --primary:#6d96ff; --primary2:#8b7cff; --primary-weak:#18233d;\n    --grad:linear-gradient(135deg,#3b82f6,#6d5ae8);\n    --bg:#0a0f1b; --card:#121a2b; --line:#223050; --line2:#1b2740;\n    --text:#e8eef9; --text2:#93a1bf; --text3:#5d6b8a;\n    --red:#f87171; --red-bg:rgba(248,113,113,.12); --red-t:#fca5a5;\n    --orange:#fb923c; --orange-bg:rgba(251,146,60,.13);\n    --green:#4ade80; --green-bg:rgba(74,222,128,.12);\n    --blue-bg:rgba(96,165,250,.13);\n    --shadow:0 1px 2px rgba(0,0,0,.3), 0 8px 24px rgba(0,0,0,.35);\n    --shadow-lift:0 4px 12px rgba(0,0,0,.35), 0 16px 40px rgba(59,130,246,.18);\n    --glass:rgba(13,20,35,.82);\n  }\n  *{box-sizing:border-box;margin:0;padding:0}\n  html{-webkit-text-size-adjust:100%}\n  body{\n    font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;\n    background:var(--bg); color:var(--text); font-size:14px; line-height:1.55;\n    padding-bottom:env(safe-area-inset-bottom);\n    -webkit-font-smoothing:antialiased;\n  }\n  body::before{\n    content:\"\"; position:fixed; inset:0; z-index:0; pointer-events:none;\n    background:\n      radial-gradient(640px 320px at 88% -60px, rgba(124,58,237,.10), transparent 70%),\n      radial-gradient(560px 320px at -80px 32%, rgba(6,182,212,.09), transparent 70%);\n  }\n  html[data-theme=\"dark\"] body::before{\n    background:\n      radial-gradient(640px 320px at 88% -60px, rgba(99,102,241,.14), transparent 70%),\n      radial-gradient(560px 320px at -80px 32%, rgba(6,182,212,.08), transparent 70%);\n  }\n  button{font-family:inherit;font-size:14px;cursor:pointer;border:none;background:none;color:inherit}\n  button:active{transform:scale(.97)}\n  input,select,textarea{font-family:inherit;font-size:16px;color:var(--text)}\n  a{color:var(--primary);text-decoration:none}\n  svg{display:block}\n\n  /* ===== 顶栏 ===== */\n  .topbar{\n    position:sticky;top:0;z-index:50;display:flex;align-items:center;gap:10px;\n    padding:10px 16px;background:var(--glass);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);\n    border-bottom:1px solid var(--line);\n  }\n  .brand{display:flex;align-items:center;gap:9px;font-weight:800;font-size:16px;white-space:nowrap;flex-shrink:0;letter-spacing:-.2px}\n  #brandIcon{\n    width:30px;height:30px;border-radius:9px;background:var(--grad);\n    display:flex;align-items:center;justify-content:center;color:#fff;\n    box-shadow:0 3px 10px rgba(37,99,235,.35);flex-shrink:0;\n  }\n  .brand .bt{display:flex;flex-direction:column;line-height:1.15}\n  .brand .bt small{font-size:10px;font-weight:500;color:var(--text3);letter-spacing:.5px}\n  .nav{display:flex;gap:5px;overflow-x:auto;flex:1;scrollbar-width:none;padding:2px;mask-image:linear-gradient(90deg,#000 92%,transparent)}\n  .nav::-webkit-scrollbar{display:none}\n  .chip{\n    display:inline-flex;align-items:center;gap:6px;padding:7px 13px;border-radius:99px;\n    color:var(--text2);white-space:nowrap;min-height:38px;border:1px solid transparent;\n    transition:.15s;\n  }\n  .chip:hover{background:var(--line2);color:var(--text)}\n  .chip.active{background:var(--grad);color:#fff;border-color:transparent;font-weight:600;box-shadow:0 3px 10px rgba(37,99,235,.3)}\n  .topbar-actions{display:flex;align-items:center;gap:2px;flex-shrink:0}\n  .icon-btn{\n    display:inline-flex;align-items:center;justify-content:center;\n    width:44px;height:44px;border-radius:12px;color:var(--text2);transition:.15s;\n  }\n  .icon-btn:hover{background:var(--line2);color:var(--text)}\n  @media (max-width:720px){\n    .topbar{flex-wrap:wrap;padding:8px 12px 0;gap:4px}\n    .topbar-actions{margin-left:auto}\n    .nav{order:3;flex-basis:100%;padding:6px 0 8px}\n    .global-status{display:none}\n    .brand .bt small{display:none}\n  }\n\n  main{position:relative;z-index:1;max-width:1080px;margin:0 auto;padding:18px 16px 70px}\n\n  /* ===== 演示提示 ===== */\n  .demo-banner{\n    max-width:1080px;margin:14px auto 0;padding:11px 16px;display:flex;align-items:center;gap:10px;\n    background:linear-gradient(135deg,rgba(251,146,60,.12),rgba(251,146,60,.06));\n    border:1px solid rgba(251,146,60,.35);color:var(--orange);border-radius:var(--radius);\n    font-size:13px;animation:rise .3s ease both;\n  }\n  .demo-banner button{margin-left:auto;color:var(--orange);text-decoration:underline;font-size:13px;min-height:44px;font-weight:600}\n  .demo-banner .close{margin-left:0;text-decoration:none;font-size:18px;min-width:44px}\n  .hidden{display:none!important}\n\n  /* ===== 卡片通用 ===== */\n  .card{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow)}\n  @keyframes rise{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}\n\n  /* ===== 今天要处理 ===== */\n  .today{margin-bottom:18px;overflow:hidden;animation:rise .35s ease both}\n  .today-head{display:flex;align-items:center;gap:9px;padding:15px 18px;border-bottom:1px solid var(--line2)}\n  .today-head>svg{width:19px;height:19px;color:var(--primary)}\n  .today-head h2{font-size:15.5px;font-weight:700}\n  .pill{\n    background:linear-gradient(135deg,#ef4444,#dc2626);color:#fff;font-size:12px;font-weight:700;\n    border-radius:99px;padding:2px 9px;min-width:22px;text-align:center;box-shadow:0 2px 8px rgba(220,38,38,.35);\n  }\n  .pill.zero{background:var(--line);color:var(--text3);box-shadow:none}\n  .today-head .fold{margin-left:auto;color:var(--text2);width:44px;height:44px;border-radius:10px;display:flex;align-items:center;justify-content:center}\n  .today-head .fold svg{width:17px;height:17px;color:var(--text2);transition:transform .25s}\n  .today.closed .fold svg{transform:rotate(-90deg)}\n  .t-item{display:flex;align-items:center;gap:12px;padding:9px 18px;border-bottom:1px solid var(--line2);animation:rise .3s ease both}\n  .t-item:last-of-type{border-bottom:none}\n  .t-item::before{content:\"\";position:absolute}\n  .t-dot{width:8px;height:8px;border-radius:99px;flex-shrink:0;position:relative}\n  .t-item.overdue .t-dot{background:var(--red);box-shadow:0 0 0 4px var(--red-bg);animation:pulse 2s infinite}\n  .t-item.warn .t-dot{background:var(--orange);box-shadow:0 0 0 4px var(--orange-bg)}\n  .t-item.today .t-dot{background:var(--primary);box-shadow:0 0 0 4px var(--primary-weak)}\n  @keyframes pulse{50%{box-shadow:0 0 0 7px var(--red-bg)}}\n  .t-item.overdue{background:linear-gradient(90deg,var(--red-bg),transparent 70%)}\n  .t-main{flex:1;min-width:0}\n  .t-title{font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n  .t-meta{font-size:12px;color:var(--text2);margin-top:1px}\n  .t-item.overdue .t-title::before{content:\"逾期\";font-size:11px;color:#fff;background:linear-gradient(135deg,#ef4444,#dc2626);border-radius:5px;padding:1.5px 6px;margin-right:7px;font-weight:500;vertical-align:1.5px}\n  .t-item.warn .t-title::before{content:\"顺延\";font-size:11px;color:#fff;background:linear-gradient(135deg,#fb923c,#ea580c);border-radius:5px;padding:1.5px 6px;margin-right:7px;font-weight:500;vertical-align:1.5px}\n  .t-actions{display:flex;gap:7px;flex-shrink:0}\n  .btn{\n    display:inline-flex;align-items:center;justify-content:center;gap:5px;\n    min-height:44px;padding:8px 16px;border-radius:var(--radius-s);border:1px solid var(--line);\n    background:var(--card);color:var(--text);font-weight:600;transition:.15s;\n  }\n  .btn:hover{border-color:var(--primary);color:var(--primary);box-shadow:0 2px 10px rgba(37,99,235,.15)}\n  .btn.primary{background:var(--grad);border-color:transparent;color:#fff;box-shadow:0 3px 12px rgba(37,99,235,.32)}\n  .btn.primary:hover{filter:brightness(1.08);color:#fff}\n  .btn.danger{background:linear-gradient(135deg,#ef4444,#dc2626);border-color:transparent;color:#fff}\n  .btn.ghost{border-color:transparent;background:transparent;color:var(--text2)}\n  .btn.ghost:hover{color:var(--text);background:var(--line2);box-shadow:none}\n  .btn.small{min-height:44px;padding:6px 13px;font-size:13px;border-radius:10px}\n  .t-actions .btn svg,.btn.small svg{width:14px;height:14px}\n  .todo-form{display:flex;gap:9px;padding:13px 18px;background:var(--line2);border-top:1px solid var(--line2)}\n  .todo-form input{flex:1;border:1px solid var(--line);border-radius:var(--radius-s);padding:9px 13px;background:var(--card);min-height:44px;transition:.15s}\n  .todo-form input:focus{outline:none;border-color:var(--primary);box-shadow:0 0 0 3px var(--primary-weak)}\n  .empty{padding:34px 16px;text-align:center;color:var(--text2);animation:rise .3s ease both}\n  .empty svg{width:42px;height:42px;color:var(--text3);margin:0 auto 10px}\n\n  /* ===== 区块标题 ===== */\n  .sec-title{display:flex;align-items:center;gap:8px;margin:6px 0 14px;font-size:15.5px;font-weight:700}\n  .sec-title svg{color:var(--primary)}\n  .sec-title .sub{font-weight:400;font-size:12px;color:var(--text3)}\n\n  /* ===== 总览 ===== */\n  .ov-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:14px}\n  .ov-card{padding:18px;display:flex;flex-direction:column;gap:13px;transition:.2s;cursor:pointer;position:relative;overflow:hidden;animation:rise .4s ease both}\n  .ov-card::after{content:\"\";position:absolute;top:0;left:0;right:0;height:3px;background:var(--sc,#2563eb);opacity:0;transition:.2s}\n  .ov-card:hover{transform:translateY(-3px);box-shadow:var(--shadow-lift);border-color:transparent}\n  .ov-card:hover::after{opacity:1}\n  .ov-card:nth-child(2){animation-delay:.04s}.ov-card:nth-child(3){animation-delay:.08s}\n  .ov-card:nth-child(4){animation-delay:.12s}.ov-card:nth-child(5){animation-delay:.16s}\n  .ov-card:nth-child(6){animation-delay:.2s}\n  .ov-head{display:flex;align-items:center;gap:10px}\n  .ov-ico{width:38px;height:38px;border-radius:11px;display:flex;align-items:center;justify-content:center;color:var(--sc,#2563eb);background:var(--sc-bg,var(--primary-weak));flex-shrink:0}\n  .ov-head h3{font-size:15px;font-weight:700;flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n  .ov-metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}\n  .ov-metric{background:var(--line2);border-radius:11px;padding:10px 11px}\n  .ov-metric .v{\n    font-size:20px;font-weight:800;letter-spacing:-.4px;font-variant-numeric:tabular-nums;\n    background:linear-gradient(135deg,var(--text),var(--text2));-webkit-background-clip:text;background-clip:text;color:transparent;\n  }\n  .ov-metric .v .u{font-size:11px;font-weight:500;color:var(--text3);margin-left:2px;-webkit-text-fill-color:var(--text3)}\n  .ov-metric .l{font-size:11px;color:var(--text2);margin-top:1px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n  .ov-foot{display:flex;align-items:center;gap:8px}\n  .ov-foot .arrow{margin-left:auto;color:var(--text3);display:flex;align-items:center;transition:.2s}\n  .ov-card:hover .arrow{color:var(--primary);transform:translateX(3px)}\n  .ov-foot .arrow svg{width:16px;height:16px}\n\n  /* 服务专属色 */\n  .svc-c-downloads{--sc:#2563eb;--sc-bg:#eff6ff}\n  .svc-c-errors{--sc:#dc2626;--sc-bg:#fef2f2}\n  .svc-c-tickets{--sc:#7c3aed;--sc-bg:#f5f3ff}\n  .svc-c-mods{--sc:#ea580c;--sc-bg:#fff7ed}\n  .svc-c-blog{--sc:#db2777;--sc-bg:#fdf2f8}\n  .svc-c-wiki{--sc:#0891b2;--sc-bg:#ecfeff}\n  html[data-theme=\"dark\"] .svc-c-downloads{--sc:#60a5fa;--sc-bg:rgba(59,130,246,.14)}\n  html[data-theme=\"dark\"] .svc-c-errors{--sc:#f87171;--sc-bg:rgba(248,113,113,.13)}\n  html[data-theme=\"dark\"] .svc-c-tickets{--sc:#a78bfa;--sc-bg:rgba(139,92,246,.15)}\n  html[data-theme=\"dark\"] .svc-c-mods{--sc:#fb923c;--sc-bg:rgba(249,115,22,.14)}\n  html[data-theme=\"dark\"] .svc-c-blog{--sc:#f472b6;--sc-bg:rgba(236,72,153,.14)}\n  html[data-theme=\"dark\"] .svc-c-wiki{--sc:#22d3ee;--sc-bg:rgba(6,182,212,.13)}\n\n  .dot{width:9px;height:9px;border-radius:99px;flex-shrink:0}\n  .dot.ok{background:var(--green);box-shadow:0 0 0 3.5px var(--green-bg)}\n  .dot.demo{background:var(--orange);box-shadow:0 0 0 3.5px var(--orange-bg)}\n  .dot.error{background:var(--red);box-shadow:0 0 0 3.5px var(--red-bg);animation:pulse 2s infinite}\n  .dot.idle{background:var(--text3)}\n  .dot.loading{background:var(--primary);animation:blink 1s infinite}\n  @keyframes blink{50%{opacity:.3}}\n  .badge{display:inline-flex;align-items:center;font-size:11.5px;border-radius:7px;padding:2.5px 8px;font-weight:600}\n  .badge.b-red{background:var(--red-bg);color:var(--red-t)}\n  .badge.b-orange{background:var(--orange-bg);color:var(--orange)}\n  .badge.b-green{background:var(--green-bg);color:var(--green)}\n  .badge.b-blue{background:var(--blue-bg);color:var(--primary)}\n  .badge.b-gray{background:var(--line2);color:var(--text2)}\n\n  /* ===== 子页 ===== */\n  .svc-head{display:flex;align-items:center;gap:11px;flex-wrap:wrap;margin-bottom:16px;animation:rise .3s ease both}\n  .svc-head .ov-ico{width:44px;height:44px;border-radius:13px}\n  .svc-head h2{font-size:19px;font-weight:800;letter-spacing:-.3px}\n  .svc-head .desc{font-size:12.5px;color:var(--text2);width:100%;padding-left:55px;margin-top:-7px}\n  .svc-head .grow{flex:1}\n  .metric-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(155px,1fr));gap:13px;margin-bottom:16px}\n  .metric-card{padding:17px;animation:rise .35s ease both;position:relative;overflow:hidden}\n  .metric-card:nth-child(2){animation-delay:.05s}.metric-card:nth-child(3){animation-delay:.1s}\n  .metric-card:nth-child(4){animation-delay:.15s}.metric-card:nth-child(5){animation-delay:.2s}.metric-card:nth-child(6){animation-delay:.25s}\n  .metric-card .v{font-size:28px;font-weight:800;letter-spacing:-.6px;font-variant-numeric:tabular-nums}\n  .metric-card .v .u{font-size:12px;font-weight:500;color:var(--text3);margin-left:3px}\n  .metric-card .l{font-size:12.5px;color:var(--text2);margin-top:3px}\n  .metric-card.warn::before{content:\"\";position:absolute;top:0;left:0;right:0;height:3px;background:linear-gradient(90deg,#ef4444,#f97316)}\n  .metric-card.warn .v{color:var(--red)}\n  .tbl-wrap{overflow-x:auto;border-radius:var(--radius);animation:rise .4s ease both}\n  .tbl-wrap.card{box-shadow:var(--shadow)}\n  table{width:100%;border-collapse:collapse;min-width:600px}\n  th{font-size:12px;font-weight:600;color:var(--text2);text-align:left;background:var(--line2);padding:11px 15px;border-bottom:1px solid var(--line);white-space:nowrap}\n  td{padding:12px 15px;border-bottom:1px solid var(--line2);font-size:13.5px;vertical-align:middle}\n  tr:last-child td{border-bottom:none}\n  tbody tr{transition:background .15s}\n  tbody tr:hover{background:var(--line2)}\n  td.num{font-variant-numeric:tabular-nums;font-weight:700}\n  .note{font-size:12px;color:var(--text2);padding:10px 15px;background:var(--line2);border-top:1px solid var(--line2);border-radius:0 0 var(--radius) var(--radius)}\n  .err-box{padding:14px 16px;background:var(--red-bg);border:1px solid rgba(220,38,38,.3);border-radius:var(--radius);color:var(--red-t);font-size:13px;display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:16px;animation:rise .3s ease both}\n  .err-box .btn{min-height:44px;padding:6px 14px;font-size:13px}\n\n  /* ===== 表格移动端 → 卡片列表 ===== */\n  @media (max-width:640px){\n    .tbl-wrap table{min-width:0;display:block}\n    .tbl-wrap thead{display:none}\n    .tbl-wrap tbody{display:block}\n    .tbl-wrap tr{display:block;border:1px solid var(--line);border-radius:14px;margin-bottom:10px;padding:5px 0;background:var(--card);box-shadow:var(--shadow)}\n    .tbl-wrap td{display:flex;justify-content:space-between;align-items:center;gap:14px;border:none;padding:9px 15px;text-align:right}\n    .tbl-wrap td::before{content:attr(data-label);font-size:12px;color:var(--text2);flex-shrink:0;text-align:left;font-weight:500}\n    .tbl-wrap td:only-child::before{display:none}\n  }\n\n  /* ===== 登录门禁 ===== */\n  #loginGate{\n    position:fixed;inset:0;z-index:300;background:var(--bg);\n    display:flex;align-items:center;justify-content:center;padding:20px;\n  }\n  #loginGate::before{\n    content:\"\";position:absolute;inset:0;pointer-events:none;\n    background:\n      radial-gradient(700px 380px at 85% -60px, rgba(124,58,237,.16), transparent 70%),\n      radial-gradient(600px 380px at -80px 40%, rgba(6,182,212,.13), transparent 70%);\n  }\n  .login-card{\n    position:relative;width:min(380px,100%);background:var(--card);\n    border:1px solid var(--line);border-radius:22px;padding:32px 28px 24px;\n    box-shadow:var(--shadow-lift);animation:rise .45s ease both;\n  }\n  .login-logo{\n    width:54px;height:54px;border-radius:15px;background:var(--grad);color:#fff;\n    display:flex;align-items:center;justify-content:center;margin:0 auto 14px;\n    box-shadow:0 8px 22px rgba(37,99,235,.4);\n  }\n  .login-card h1{font-size:19px;text-align:center;font-weight:800;letter-spacing:-.2px}\n  .login-sub{text-align:center;color:var(--text2);font-size:13px;margin:4px 0 22px}\n  .login-field{margin-bottom:13px}\n  .login-field label{display:block;font-size:12.5px;color:var(--text2);margin-bottom:5px;font-weight:500}\n  .login-field input{\n    width:100%;border:1px solid var(--line);border-radius:11px;padding:11px 13px;\n    background:var(--card);min-height:46px;transition:.15s;\n  }\n  .login-field input:focus{outline:none;border-color:var(--primary);box-shadow:0 0 0 3px var(--primary-weak)}\n  .login-err{\n    background:var(--red-bg);color:var(--red-t);border:1px solid rgba(220,38,38,.3);\n    border-radius:10px;padding:9px 12px;font-size:12.5px;margin-bottom:13px;text-align:center;\n  }\n  .login-tip{text-align:center;color:var(--text3);font-size:11.5px;margin-top:14px}\n  #loginForm .chk{justify-content:center;margin:2px 0 14px}\n\n  /* ===== 抽屉 / 弹窗 ===== */\n  .overlay{position:fixed;inset:0;background:rgba(8,12,24,.5);backdrop-filter:blur(3px);z-index:100;display:flex;align-items:stretch;justify-content:flex-end}\n  html[data-theme=\"dark\"] .overlay{background:rgba(0,0,0,.6)}\n  .overlay.center{align-items:center;justify-content:center;padding:20px}\n  .drawer{background:var(--card);width:min(580px,100%);display:flex;flex-direction:column;animation:slideIn .25s cubic-bezier(.3,.9,.3,1);border-left:1px solid var(--line)}\n  @keyframes slideIn{from{transform:translateX(60px);opacity:.3}}\n  .drawer-head{display:flex;align-items:center;justify-content:space-between;padding:16px 20px;border-bottom:1px solid var(--line);background:linear-gradient(135deg,var(--primary-weak),transparent)}\n  .drawer-head h2{font-size:16px;font-weight:800}\n  .drawer-body{flex:1;overflow-y:auto;padding:16px 20px;-webkit-overflow-scrolling:touch}\n  .drawer-foot{display:flex;gap:10px;justify-content:flex-end;padding:14px 20px;border-top:1px solid var(--line);background:var(--line2);padding-bottom:calc(14px + env(safe-area-inset-bottom))}\n  .modal{background:var(--card);border-radius:18px;max-width:400px;width:100%;padding:22px;box-shadow:var(--shadow-lift);animation:rise .25s ease both;border:1px solid var(--line)}\n  .modal h3{font-size:15.5px;margin-bottom:8px;font-weight:700}\n  .modal p{font-size:13.5px;color:var(--text2);margin-bottom:18px}\n  .modal .btn-row{display:flex;gap:10px;justify-content:flex-end}\n\n  .help-box{background:var(--blue-bg);border:1px solid rgba(37,99,235,.25);border-radius:13px;padding:13px 15px;font-size:12.5px;color:var(--primary);margin-bottom:18px;animation:rise .3s ease both}\n  .help-box b{display:block;margin-bottom:5px;font-weight:700}\n  .help-box ol{padding-left:18px;display:grid;gap:3px}\n  .help-box code{background:var(--card);border:1px solid var(--line);border-radius:5px;padding:0 5px;font-size:11.5px}\n  .drawer h3{font-size:13px;color:var(--text2);margin:20px 0 11px;padding-bottom:7px;border-bottom:1px solid var(--line);font-weight:700;letter-spacing:.3px}\n  .drawer h3:first-child{margin-top:0}\n  .form-row{margin-bottom:12px}\n  .form-row>label{display:block;font-size:12.5px;color:var(--text2);margin-bottom:5px;font-weight:500}\n  .form-row input[type=text],.form-row input[type=number],.form-row input:not([type]),.form-row select,.form-row textarea{\n    width:100%;border:1px solid var(--line);border-radius:10px;padding:9px 12px;background:var(--card);min-height:44px;transition:.15s;\n  }\n  .form-row textarea{min-height:0;resize:vertical;line-height:1.55;font-size:16px;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}\n  .form-row input:focus,.form-row select:focus,.form-row textarea:focus{outline:none;border-color:var(--primary);box-shadow:0 0 0 3px var(--primary-weak)}\n  .grid2{display:grid;grid-template-columns:1fr 1fr;gap:10px}\n  .grid3{display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px}\n  @media (max-width:560px){.grid3{grid-template-columns:1fr}.grid2{grid-template-columns:1fr}}\n  .chk{display:flex;align-items:center;gap:9px;font-size:13.5px;margin-bottom:12px;cursor:pointer;min-height:44px}\n  .chk input{width:19px;height:19px;accent-color:var(--primary)}\n  .svc-block{border:1px solid var(--line);border-radius:14px;margin-bottom:10px;overflow:hidden;background:var(--card)}\n  .svc-block summary{\n    display:flex;align-items:center;gap:10px;padding:13px 15px;cursor:pointer;user-select:none;\n    font-weight:700;font-size:14px;list-style:none;min-height:52px;transition:background .15s;\n  }\n  .svc-block summary:hover{background:var(--line2)}\n  .svc-block summary::-webkit-details-marker{display:none}\n  .svc-block summary .s-ico{width:30px;height:30px;border-radius:9px;display:flex;align-items:center;justify-content:center;color:var(--sc,#2563eb);background:var(--sc-bg,var(--primary-weak));flex-shrink:0}\n  .svc-block summary .s-ico svg{width:15px;height:15px}\n  .svc-block summary .tag{margin-left:auto;font-size:11px;font-weight:600}\n  .svc-form{padding:4px 15px 16px;border-top:1px solid var(--line);background:var(--line2)}\n  .btn-row{display:flex;gap:10px;flex-wrap:wrap;margin-top:6px}\n  .test-result{background:#0b1222;color:#a5f3d0;border-radius:11px;padding:11px 13px;font-size:12px;white-space:pre-wrap;word-break:break-all;max-height:240px;overflow:auto;margin-top:10px;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;border:1px solid var(--line)}\n  .test-result.good{color:#86efac}\n  .test-result.bad{color:#fca5a5}\n\n  /* ===== toast ===== */\n  #toast{\n    position:fixed;left:50%;bottom:calc(30px + env(safe-area-inset-bottom));transform:translateX(-50%) translateY(20px);z-index:200;\n    background:var(--text);color:var(--bg);padding:12px 19px;border-radius:99px;font-size:13.5px;font-weight:600;\n    opacity:0;pointer-events:none;transition:.25s;max-width:86vw;text-align:center;\n    box-shadow:0 10px 30px rgba(15,23,42,.3);\n  }\n  #toast.show{opacity:1;transform:translateX(-50%) translateY(0)}\n  #toast.err{background:var(--red);color:#fff}\n  #toast.good{background:var(--green);color:#fff}\n\n  @media (max-width:720px){\n    main{padding:14px 12px 46px}\n    .metric-grid{grid-template-columns:repeat(2,1fr)}\n    .ov-grid{grid-template-columns:1fr}\n    .svc-head h2{font-size:17px}\n    .svc-head .desc{padding-left:0;margin-top:0}\n    .t-actions .btn{padding:6px 11px}\n  }\n  @media (prefers-reduced-motion:reduce){\n    *,*::before,*::after{animation-duration:.01ms!important;transition-duration:.01ms!important}\n  }\n  /* 运行模式显隐与徽章 */\n  html[data-runtime=\"server\"] .only-local{display:none!important}\n  html[data-runtime=\"local\"] .only-server{display:none!important}\n  .runtime-badge{\n    display:inline-flex;align-items:center;gap:7px;padding:7px 13px;border-radius:99px;\n    font-size:12.5px;font-weight:600;margin-bottom:14px;border:1px solid var(--line);background:var(--line2);color:var(--text2);\n  }\n  .runtime-badge .rdot{width:8px;height:8px;border-radius:99px;background:var(--text3)}\n  .runtime-badge.server{background:var(--green-bg);border-color:rgba(22,163,74,.35);color:var(--green)}\n  .runtime-badge.server .rdot{background:var(--green)}\n  .login-tip{color:var(--primary)!important;font-weight:600}\n</style>\n</head>\n<body>\n\n<!-- 登录门禁（前端校验，防路人误入） -->\n<div id=\"loginGate\" class=\"hidden\">\n  <div class=\"login-card\">\n    <div class=\"login-logo\" id=\"loginLogo\"></div>\n    <h1 id=\"loginTitle\">聚合工作台</h1>\n    <p class=\"login-sub\">请登录以继续访问</p>\n    <p class=\"login-tip\" id=\"runtimeTip\">本地模式 · 数据存本机浏览器</p>\n    <form id=\"loginForm\" autocomplete=\"off\">\n      <div class=\"login-field\"><label for=\"loginUser\">账号</label><input id=\"loginUser\" type=\"text\" placeholder=\"账号\" autocomplete=\"username\"></div>\n      <div class=\"login-field\"><label for=\"loginPass\">密码</label><input id=\"loginPass\" type=\"password\" placeholder=\"密码\" autocomplete=\"current-password\"></div>\n      <label class=\"chk\" style=\"justify-content:center\"><input type=\"checkbox\" id=\"loginRemember\" checked> 7 天内免登录</label>\n      <div id=\"loginError\" class=\"login-err hidden\"></div>\n      <button class=\"btn primary\" type=\"submit\" id=\"loginBtn\" style=\"width:100%;font-size:15px;letter-spacing:6px\">登录</button>\n      <p class=\"login-tip\">密码由部署者在页面 WB_ENV 变量区配置</p>\n    </form>\n  </div>\n</div>\n\n<header class=\"topbar\">\n  <div class=\"brand\">\n    <span id=\"brandIcon\"></span>\n    <span class=\"bt\"><span id=\"brandName\">聚合工作台</span><small>SERVICE HUB</small></span>\n  </div>\n  <nav class=\"nav\" id=\"mainNav\"></nav>\n  <div class=\"topbar-actions\">\n    <span class=\"global-status\" id=\"globalStatus\"></span>\n    <button class=\"icon-btn\" id=\"btnTheme\" title=\"切换主题\"></button>\n    <button class=\"icon-btn\" id=\"btnRefresh\" title=\"刷新数据\"></button>\n    <button class=\"icon-btn\" id=\"btnExportTop\" title=\"导出 JSON 备份\"></button>\n    <button class=\"icon-btn\" id=\"btnSettings\" title=\"设置 / API 接入\"></button>\n  </div>\n</header>\n\n<div class=\"demo-banner hidden\" id=\"demoBanner\">\n  <span id=\"demoBannerText\">演示模式：部分数据为内置示例。</span>\n  <button data-action=\"open-settings\">接入我的 API</button>\n  <button class=\"close\" data-action=\"close-banner\" title=\"关闭提示\">×</button>\n</div>\n\n<main id=\"main\">\n  <!-- 今天要处理（置顶） -->\n  <section class=\"today card\" id=\"todaySection\">\n    <div class=\"today-head\">\n      <span id=\"clockIcon\"></span>\n      <h2>今天要处理</h2>\n      <span class=\"pill\" id=\"todayCount\">0</span>\n      <button class=\"fold\" data-action=\"toggle-today\" id=\"todayFoldBtn\" title=\"收起/展开\"></button>\n    </div>\n    <div id=\"todayBody\">\n      <div id=\"todayList\"></div>\n      <form class=\"todo-form\" id=\"todoForm\">\n        <input id=\"todoInput\" type=\"text\" placeholder=\"添加快速待办，回车或点击按钮\" maxlength=\"80\">\n        <button type=\"submit\" class=\"btn primary small\" id=\"todoAddBtn\">添加</button>\n      </form>\n    </div>\n  </section>\n\n  <!-- 总览 -->\n  <section id=\"viewOverview\"></section>\n  <!-- 服务子页 -->\n  <section id=\"viewService\"></section>\n</main>\n\n<!-- 设置抽屉 -->\n<div class=\"overlay hidden\" id=\"settingsOverlay\">\n  <div class=\"drawer\">\n    <div class=\"drawer-head\">\n      <h2>设置 · API 接入</h2>\n      <button class=\"icon-btn\" data-action=\"close-settings\" id=\"btnCloseSettings\"></button>\n    </div>\n    <div class=\"drawer-body\">\n      <div class=\"runtime-badge\" id=\"runtimeBadge\"></div>\n      <div class=\"help-box\">\n        <b>接入指南</b>\n        <ol>\n          <li>填入服务的 <b>API 地址</b>（需返回 JSON，可含认证）</li>\n          <li>选择认证方式并填入 Token（无需认证可跳过）</li>\n          <li>点「测试连接」确认返回结构</li>\n          <li>按返回的 JSON 层级修改「数据映射」路径，如 <code>data.stats.today</code>、<code>data.items</code></li>\n        </ol>\n      </div>\n      <h3>通用</h3>\n      <div class=\"form-row\"><label>工作台名称</label><input id=\"cfgBrand\" type=\"text\"></div>\n      <label class=\"chk\"><input type=\"checkbox\" id=\"cfgDemo\"> 启用演示数据（未配置 / 请求失败的服务显示内置示例）</label>\n      <div class=\"form-row\"><label>自动刷新间隔（分钟，0 = 关闭）</label><input id=\"cfgPoll\" type=\"number\" min=\"0\" step=\"1\" inputmode=\"numeric\"></div>\n      <h3>服务接入</h3>\n      <div id=\"svcForms\"></div>\n      <h3 class=\"only-local\">云同步（GitHub 仓库存储）</h3>\n      <div class=\"only-local\">\n      <div class=\"form-row\"><label>GitHub Token（细粒度 Token，仅授权 <code id=\"syncRepoName\">…</code> 的 Contents 读写；仅保存在本设备浏览器）</label><input id=\"syncToken\" type=\"password\" placeholder=\"github_pat_… 或 ghp_…，留空则不启用同步\"></div>\n      <label class=\"chk\"><input type=\"checkbox\" id=\"syncAuto\"> 自动同步（打开页面自动拉取合并；本地变更约 5 秒后自动上传）</label>\n      <label class=\"chk\"><input type=\"checkbox\" id=\"syncTokens\"> 同步包含 API Token（⚠️ 数据文件在公开仓库中任何人可读，默认关闭；开启前确认仓库为私有或数据无敏感性）</label>\n      <div class=\"btn-row\" style=\"margin-bottom:8px\">\n        <button class=\"btn\" id=\"btnSyncUp\">上传到云端</button>\n        <button class=\"btn\" id=\"btnSyncDown\">从云端恢复</button>\n      </div>\n      <p id=\"syncStatus\" style=\"font-size:12px;color:var(--text2);margin-bottom:6px\">未启用</p>\n      <p style=\"font-size:12px;color:var(--text2);margin-bottom:16px\">同步目标：<span id=\"syncTarget\"></span>。同步内容：品牌名、主题、待办、各服务名称/地址/映射等；<b>API Token 默认不参与同步</b>（需在各设备本地填写）。数据文件带完整提交历史，可在仓库中随时回溯。</p>\n      </div>\n      <div class=\"only-server\" style=\"background:var(--green-bg);border:1px solid rgba(22,163,74,.3);border-radius:11px;padding:11px 14px;font-size:12.5px;color:var(--green);margin-bottom:16px\">\n        ✓ 云端后端模式：配置、待办与<b>各服务 API Token</b> 已实时存入 Cloudflare D1，多设备登录即同步；对外 API 统一经 <code>api/proxy/&lt;服务&gt;</code> 网关集中调用，无需再配 CORS。\n      </div>\n      <h3>数据与备份</h3>\n      <div class=\"btn-row\" style=\"margin-bottom:16px\">\n        <button class=\"btn\" id=\"btnApplyEnv\" title=\"用本文件 WB_ENV 变量区中的 API 参数覆盖本地配置\">应用页面内置配置</button>\n        <button class=\"btn\" id=\"btnExport\">导出 JSON 备份</button>\n        <button class=\"btn\" id=\"btnImport\">导入恢复</button>\n        <button class=\"btn danger\" id=\"btnWipe\">清空全部数据</button>\n      </div>\n      <p style=\"font-size:12px;color:var(--text2);margin-bottom:10px\">「应用页面内置配置」会把部署文件 WB_ENV 变量区里的 API 参数覆盖到本设备（含 Token）。API 参数也可直接修改部署文件顶部的 WB_ENV 后重新部署，对所有设备生效。</p>\n      <p style=\"font-size:12px;color:var(--text2);margin-bottom:10px\">登录密码在部署文件的 <code>WB_ENV.LOGIN</code> 中修改（PASS_SHA256 = sha256(SALT+新密码)），登录凭据校验仅存于页面内。</p>\n      <p style=\"font-size:12px;color:var(--text2)\">手机使用技巧：用浏览器打开本页 → 分享 → 「添加到主屏幕」，即可像 App 一样全屏使用。</p>\n    </div>\n    <div class=\"drawer-foot\">\n      <button class=\"btn ghost\" data-action=\"close-settings\">取消</button>\n      <button class=\"btn primary\" id=\"btnSaveSettings\">保存设置</button>\n    </div>\n  </div>\n</div>\n\n<!-- 确认弹窗 -->\n<div class=\"overlay center hidden\" id=\"confirmModal\">\n  <div class=\"modal\">\n    <h3 id=\"confirmTitle\"></h3>\n    <p id=\"confirmText\"></p>\n    <div class=\"btn-row\">\n      <button class=\"btn ghost\" id=\"confirmNo\">取消</button>\n      <button class=\"btn danger\" id=\"confirmYes\">确认</button>\n    </div>\n  </div>\n</div>\n\n<div id=\"toast\"></div>\n<input type=\"file\" id=\"importFile\" accept=\"application/json,.json\" hidden>\n\n<script>\n\"use strict\";\n/* =========================================================\n * 聚合工作台 · 单文件版（v2 美化 + 移动适配 + 暗色模式）\n * 架构：数据层 → 计算层 → 渲染层（单向调用，统一 refreshAll 调度）\n * 存储：localStorage（key 前缀 wb_hub_）\n * ========================================================= */\n\n/* ---------- 常量 / 默认配置 ---------- */\nvar LS_CFG = \"wb_hub_config\";\nvar LS_TODOS = \"wb_hub_todos\";\nvar LS_THEME = \"wb_hub_theme\";\nvar LS_AUTH = \"wb_hub_auth_until\";  // 免登录截止时间戳\nvar LS_FAIL = \"wb_hub_login_fail\";  // {n: 失败次数, until: 锁定截止时间戳}\nvar LS_SYNC_TOKEN = \"wb_hub_sync_token\";   // GitHub Token（仅本设备）\nvar LS_SYNC_AUTO = \"wb_hub_sync_auto\";     // 自动同步开关\nvar LS_SYNC_TOKENS = \"wb_hub_sync_tokens\"; // 是否同步敏感字段\nvar LS_LAST_SYNC = \"wb_hub_last_sync\";     // 最近同步时间\n\n/* ---------- SHA-256（纯 JS 内联，用于登录口令校验） ---------- */\nfunction utf8(s) {\n  try { return unescape(encodeURIComponent(s)); } catch (e) { return String(s); }\n}\nfunction sha256(ascii) {\n  function rightRotate(v, a) { return (v >>> a) | (v << (32 - a)); }\n  var maxWord = Math.pow(2, 32), result = \"\";\n  var words = [], asciiBitLength = ascii.length * 8;\n  var hash = [], k = [], primeCounter = 0, isComposite = {};\n  for (var candidate = 2; primeCounter < 64; candidate++) {\n    if (!isComposite[candidate]) {\n      for (var i = 0; i < 313; i += candidate) isComposite[i] = candidate;\n      hash[primeCounter] = (Math.pow(candidate, 0.5) * maxWord) | 0;\n      k[primeCounter++] = (Math.pow(candidate, 1 / 3) * maxWord) | 0;\n    }\n  }\n  ascii += \"\\x80\";\n  while (ascii.length % 64 - 56) ascii += \"\\x00\";\n  for (i = 0; i < ascii.length; i++) {\n    var j = ascii.charCodeAt(i);\n    if (j >> 8) return \"\";\n    words[i >> 2] |= j << ((3 - i) % 4) * 8;\n  }\n  words[words.length] = (asciiBitLength / maxWord) | 0;\n  words[words.length] = asciiBitLength;\n  for (j = 0; j < words.length;) {\n    var w = words.slice(j, j += 16);\n    var oldHash = hash.slice(0);\n    for (i = 0; i < 64; i++) {\n      var w15 = w[i - 15], w2 = w[i - 2];\n      var a = hash[0], e = hash[4];\n      var temp1 = hash[7]\n        + (rightRotate(e, 6) ^ rightRotate(e, 11) ^ rightRotate(e, 25))\n        + ((e & hash[5]) ^ ((~e) & hash[6]))\n        + k[i]\n        + (w[i] = (i < 16) ? w[i] : (\n          w[i - 16]\n          + (rightRotate(w15, 7) ^ rightRotate(w15, 18) ^ (w15 >>> 3))\n          + w[i - 7]\n          + (rightRotate(w2, 17) ^ rightRotate(w2, 19) ^ (w2 >>> 10))\n        )) | 0;\n      var temp2 = (rightRotate(a, 2) ^ rightRotate(a, 13) ^ rightRotate(a, 22))\n        + ((a & hash[1]) ^ (a & hash[2]) ^ (hash[1] & hash[2]));\n      hash = [(temp1 + temp2) | 0].concat(hash);\n      hash[4] = (hash[4] + temp1) | 0;\n      hash.pop();\n    }\n    for (i = 0; i < 8; i++) hash[i] = (hash[i] + oldHash[i]) | 0;\n  }\n  for (i = 0; i < 8; i++) {\n    for (j = 3; j + 1; j--) {\n      var b = (hash[i] >> (j * 8)) & 255;\n      result += ((b < 16) ? 0 : \"\") + b.toString(16);\n    }\n  }\n  return result;\n}\nfunction passHash(pwd) { return sha256(utf8(String((window.WB_ENV && window.WB_ENV.LOGIN && window.WB_ENV.LOGIN.SALT) || \"\") + utf8(pwd))); }\n\nvar ICONS = {\n  hub: '<rect x=\"3\" y=\"3\" width=\"7\" height=\"7\" rx=\"1.8\"/><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\" rx=\"1.8\"/><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\" rx=\"1.8\"/><rect x=\"14\" y=\"14\" width=\"7\" height=\"7\" rx=\"1.8\"/>',\n  downloads: '<path d=\"M12 3v12\"/><path d=\"M7 10l5 5 5-5\"/><path d=\"M4 19h16\"/>',\n  errors: '<path d=\"M12 3 2.5 20h19L12 3z\"/><path d=\"M12 10v4\"/><path d=\"M12 17.2v.3\"/>',\n  tickets: '<path d=\"M9 6h12\"/><path d=\"M9 12h12\"/><path d=\"M9 18h12\"/><path d=\"M3.5 5.5 5 7l2.5-2.5\"/><path d=\"M3.5 11.5 5 13l2.5-2.5\"/><path d=\"M3.5 17.5 5 19l2.5-2.5\"/>',\n  mods: '<path d=\"M21 12a9 9 0 1 1-2.9-6.6\"/><path d=\"M21 3v6h-6\"/>',\n  blog: '<path d=\"M4 20l4.5-1L20 7.5a2.1 2.1 0 0 0-3-3L5.5 16 4 20z\"/><path d=\"M13.5 6.5l3 3\"/>',\n  wiki: '<path d=\"M4 20V6a2 2 0 0 1 2-2h13v14H6a2 2 0 0 0-2 2z\"/><path d=\"M19 18v3H6a2 2 0 0 1-2-2\"/>',\n  gear: '<circle cx=\"12\" cy=\"12\" r=\"3.5\"/><path d=\"M12 2.5v3M12 18.5v3M2.5 12h3M18.5 12h3M5.2 5.2l2.1 2.1M16.7 16.7l2.1 2.1M18.8 5.2l-2.1 2.1M7.3 16.7l-2.1 2.1\"/>',\n  refresh: '<path d=\"M21 12a9 9 0 1 1-2.9-6.6\"/><path d=\"M21 3v6h-6\"/>',\n  export: '<path d=\"M12 15V3\"/><path d=\"M7 8l5-5 5 5\"/><path d=\"M4 19h16\"/>',\n  x: '<path d=\"M6 6l12 12\"/><path d=\"M18 6 6 18\"/>',\n  clock: '<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7v5l3.2 2\"/>',\n  chevron: '<path d=\"M9 6l6 6-6 6\"/>',\n  out: '<path d=\"M14 5h5v5\"/><path d=\"M19 5l-8 8\"/><path d=\"M19 13.5V18a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2h4.5\"/>',\n  check: '<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M8.5 12.5 11 15l4.5-5.5\"/>',\n  moon: '<path d=\"M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8z\"/>',\n  sun: '<circle cx=\"12\" cy=\"12\" r=\"4\"/><path d=\"M12 2.5v2.5M12 19v2.5M2.5 12H5M19 12h2.5M4.9 4.9 6.7 6.7M17.3 17.3l1.8 1.8M19.1 4.9 17.3 6.7M6.7 17.3 4.9 19.1\"/>'\n};\nfunction ic(name, size) {\n  size = size || 18;\n  return '<svg viewBox=\"0 0 24 24\" width=\"' + size + '\" height=\"' + size + '\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">' + (ICONS[name] || \"\") + \"</svg>\";\n}\n\nvar DEFAULT_MAPPING = {\n  downloads: {\n    metrics: [\n      { label: \"今日下载\", path: \"data.stats.today\", unit: \"次\" },\n      { label: \"总下载量\", path: \"data.stats.total\", unit: \"次\" },\n      { label: \"资源总数\", path: \"data.stats.files\", unit: \"个\" }\n    ],\n    list: { path: \"data.items\", columns: [\n      { title: \"文件名\", path: \"name\" },\n      { title: \"大小\", path: \"size\" },\n      { title: \"下载量\", path: \"downloads\", format: \"num\" },\n      { title: \"更新时间\", path: \"date\", format: \"time\" }\n    ]},\n    todo: null\n  },\n  errors: {\n    metrics: [\n      { label: \"未处理\", path: \"data.stats.unresolved\", unit: \"条\" },\n      { label: \"严重错误\", path: \"data.stats.critical\", unit: \"条\" },\n      { label: \"累计错误\", path: \"data.stats.total\", unit: \"条\" }\n    ],\n    list: { path: \"data.items\", columns: [\n      { title: \"编号\", path: \"id\" },\n      { title: \"错误内容\", path: \"error\" },\n      { title: \"级别\", path: \"level\", format: \"badge\" },\n      { title: \"出现次数\", path: \"count\", format: \"num\" },\n      { title: \"状态\", path: \"status\", format: \"badge\" },\n      { title: \"最后出现\", path: \"last_seen\", format: \"time\" }\n    ]},\n    todo: { listPath: \"data.items\", titlePath: \"error\", statusPath: \"status\", pendingValue: \"未处理\", datePath: \"last_seen\" }\n  },\n  tickets: {\n    metrics: [\n      { label: \"待处理\", path: \"data.stats.open\", unit: \"单\" },\n      { label: \"已逾期\", path: \"data.stats.overdue\", unit: \"单\" },\n      { label: \"累计工单\", path: \"data.stats.total\", unit: \"单\" }\n    ],\n    list: { path: \"data.items\", columns: [\n      { title: \"编号\", path: \"id\" },\n      { title: \"标题\", path: \"title\" },\n      { title: \"提交人\", path: \"user\" },\n      { title: \"优先级\", path: \"priority\", format: \"badge\" },\n      { title: \"状态\", path: \"status\", format: \"badge\" },\n      { title: \"创建时间\", path: \"created_at\", format: \"time\" }\n    ]},\n    todo: { listPath: \"data.items\", titlePath: \"title\", statusPath: \"status\", pendingValue: \"待处理\", datePath: \"created_at\" }\n  },\n  mods: {\n    metrics: [\n      { label: \"待审核\", path: \"data.stats.pending\", unit: \"个\" },\n      { label: \"已发布版本\", path: \"data.stats.published\", unit: \"个\" },\n      { label: \"收录模组\", path: \"data.stats.total_mods\", unit: \"个\" }\n    ],\n    list: { path: \"data.items\", columns: [\n      { title: \"模组\", path: \"name\" },\n      { title: \"版本\", path: \"version\" },\n      { title: \"状态\", path: \"status\", format: \"badge\" },\n      { title: \"提交时间\", path: \"date\", format: \"time\" }\n    ]},\n    todo: { listPath: \"data.items\", titlePath: \"name\", statusPath: \"status\", pendingValue: \"待审核\", datePath: \"date\" }\n  },\n  blog: {\n    metrics: [\n      { label: \"文章数\", path: \"data.stats.posts\", unit: \"篇\" },\n      { label: \"评论数\", path: \"data.stats.comments\", unit: \"条\" },\n      { label: \"总浏览量\", path: \"data.stats.views\", unit: \"次\" }\n    ],\n    list: { path: \"data.items\", columns: [\n      { title: \"标题\", path: \"title\" },\n      { title: \"浏览\", path: \"views\", format: \"num\" },\n      { title: \"评论\", path: \"comments\", format: \"num\" },\n      { title: \"发布时间\", path: \"date\", format: \"time\" }\n    ]},\n    todo: null\n  },\n  /* 真实接口：GET /api/articles → { code, msg, data:[{title,group,link,date,tags[]}], total:N } */\n  wiki: {\n    metrics: [\n      { label: \"文章总数\", path: \"total\", unit: \"篇\" },\n      { label: \"最新文章\", path: \"data[0].title\" },\n      { label: \"最新发布\", path: \"data[0].date\" }\n    ],\n    list: { path: \"data\", columns: [\n      { title: \"标题\", path: \"title\" },\n      { title: \"分组\", path: \"group\" },\n      { title: \"标签\", path: \"tags\", format: \"badge\" },\n      { title: \"发布日期\", path: \"date\", format: \"time\" }\n    ]},\n    todo: null\n  }\n};\n\nvar SVC_DEFS = [\n  { id: \"downloads\", name: \"下载站\", icon: \"downloads\", desc: \"资源下载统计与热门文件\" },\n  { id: \"errors\",    name: \"错误报告分析\", icon: \"errors\", desc: \"崩溃与异常聚合分析\" },\n  { id: \"tickets\",   name: \"工单系统\", icon: \"tickets\", desc: \"用户工单跟踪与响应\" },\n  { id: \"mods\",      name: \"模组更新平台\", icon: \"mods\", desc: \"模组版本审核与发布\" },\n  { id: \"blog\",      name: \"个人博客\", icon: \"blog\", desc: \"文章数据与近期发布\" },\n  { id: \"wiki\",      name: \"Wiki\", icon: \"wiki\", desc: \"知识库文章与标签检索\" }\n];\n\n/* 从页面 WB_ENV 变量区构建默认配置 */\nfunction buildConfigFromEnv() {\n  var env = window.WB_ENV || {};\n  var cfg = defaultConfig();\n  if (env.BRAND) cfg.brand = env.BRAND;\n  if (typeof env.DEMO_MODE === \"boolean\") cfg.demoMode = env.DEMO_MODE;\n  if (typeof env.POLL_MINUTES === \"number\" && env.POLL_MINUTES >= 0) cfg.pollMinutes = env.POLL_MINUTES;\n  var S = env.SERVICES || {};\n  cfg.services.forEach(function (svc) {\n    var e = S[svc.id];\n    if (!e) return;\n    if (e.NAME) svc.name = e.NAME;\n    if (e.URL) svc.url = e.URL;\n    if (e.API) svc.baseUrl = e.API;\n    if (e.AUTH && [\"none\", \"bearer\", \"header\"].indexOf(e.AUTH) >= 0) svc.authType = e.AUTH;\n    if (e.TOKEN) svc.token = e.TOKEN;\n    if (e.HEADER) svc.headerName = e.HEADER;\n  });\n  return cfg;\n}\n\nfunction defaultConfig() {\n  return {\n    brand: \"聚合工作台\",\n    demoMode: true,\n    pollMinutes: 0,\n    bannerClosed: false,\n    services: SVC_DEFS.map(function (d) {\n      return {\n        id: d.id, name: d.name, icon: d.icon, desc: d.desc,\n        enabled: true,\n        url: \"\",          // 服务前端地址（外链按钮）\n        baseUrl: \"\",      // API 地址（返回 JSON）\n        authType: \"none\", // none | bearer | header\n        token: \"\",\n        headerName: \"X-API-Key\",\n        advanced: DEFAULT_MAPPING[d.id]\n      };\n    })\n  };\n}\n\n/* ---------- 演示数据（相对当前时间生成，含逾期样例） ---------- */\nfunction buildDemoData() {\n  var now = Date.now(), H = 3600e3, D = 24 * H;\n  function ago(ms) { return now - ms; }\n  return {\n    downloads: { data: { stats: { today: 128, total: 45230, files: 86 }, items: [\n      { name: \"光影优化整合包 v3.2\", size: \"86.4 MB\", downloads: 3821, date: ago(2 * D) },\n      { name: \"性能增强模组包 v1.8\", size: \"24.6 MB\", downloads: 2957, date: ago(3 * D) },\n      { name: \"材质包·像素复兴 4K\", size: \"512 MB\", downloads: 1863, date: ago(5 * D) },\n      { name: \"地图·天空之城重制版\", size: \"45.2 MB\", downloads: 1240, date: ago(6 * D) },\n      { name: \"服务器基础插件合集\", size: \"12.8 MB\", downloads: 987, date: ago(8 * D) }\n    ]}},\n    errors: { data: { stats: { total: 23, unresolved: 5, critical: 2 }, items: [\n      { id: \"ERR-1042\", error: \"NullPointerException at ModLoader.init()\", level: \"critical\", count: 47, status: \"未处理\", last_seen: ago(2 * H) },\n      { id: \"ERR-1039\", error: \"Chunk load timeout (region r.3.-1.mca)\", level: \"critical\", count: 12, status: \"未处理\", last_seen: ago(9 * H) },\n      { id: \"ERR-1036\", error: \"Texture atlas overflow: 1024x1024 exceeded\", level: \"warning\", count: 156, status: \"已处理\", last_seen: ago(2 * D) },\n      { id: \"ERR-1031\", error: \"Packet 0x2F malformed from client v1.2.0\", level: \"warning\", count: 89, status: \"已处理\", last_seen: ago(3 * D) }\n    ]}},\n    tickets: { data: { stats: { total: 38, open: 6, overdue: 1 }, items: [\n      { id: \"T-2091\", title: \"安装整合包后启动闪退\", user: \"玩家_清风\", priority: \"高\", status: \"待处理\", created_at: ago(3 * D) },\n      { id: \"T-2095\", title: \"下载页验证码无法显示\", user: \"玩家_Momo\", priority: \"中\", status: \"待处理\", created_at: ago(5 * H) },\n      { id: \"T-2090\", title: \"模组兼容性问题导致掉线\", user: \"玩家_Kiro\", priority: \"中\", status: \"处理中\", created_at: ago(1 * D) },\n      { id: \"T-2087\", title: \"捐赠后未收到会员标识\", user: \"玩家_Alice\", priority: \"低\", status: \"已完成\", created_at: ago(4 * D) },\n      { id: \"T-2085\", title: \"建议增加历史版本下载\", user: \"玩家_Bob\", priority: \"低\", status: \"已完成\", created_at: ago(5 * D) }\n    ]}},\n    mods: { data: { stats: { total_mods: 12, pending: 1, published: 38 }, items: [\n      { name: \"动态光影增强\", version: \"2.1.0\", status: \"待审核\", date: ago(1 * D) },\n      { name: \"背包扩展 Plus\", version: \"1.4.2\", status: \"已发布\", date: ago(2 * D) },\n      { name: \"小地图 Radar\", version: \"3.0.1\", status: \"已发布\", date: ago(4 * D) },\n      { name: \"一键整理 Inventoria\", version: \"0.9.5\", status: \"已发布\", date: ago(6 * D) }\n    ]}},\n    blog: { data: { stats: { posts: 57, comments: 214, views: 89210 }, items: [\n      { title: \"服务器一周年：数据与回顾\", views: 1203, comments: 18, date: ago(2 * D) },\n      { title: \"模组开发入门（三）：网络包同步\", views: 986, comments: 12, date: ago(5 * D) },\n      { title: \"性能调优实录：TPS 从 12 到 19\", views: 1547, comments: 26, date: ago(8 * D) },\n      { title: \"新版本更新公告 v3.2\", views: 2301, comments: 41, date: ago(12 * D) }\n    ]}},\n    wiki: { data: { code: 0, msg: \"ok\", total: 4, data: [\n      { title: \"模组安装指南\", group: \"教程\", link: \"#\", date: ago(5 * H), tags: [\"教程\", \"入门\"] },\n      { title: \"常见崩溃排查\", group: \"问题排查\", link: \"#\", date: ago(1 * D), tags: [\"故障\"] },\n      { title: \"服务器规则\", group: \"公告\", link: \"#\", date: ago(3 * D), tags: [\"公告\", \"必读\"] },\n      { title: \"API 接口文档\", group: \"开发\", link: \"#\", date: ago(4 * D), tags: [\"开发\", \"API\"] }\n    ]}}\n  };\n}\n\n/* ---------- 状态 ---------- */\nvar state = {\n  config: null,\n  todos: [],\n  demo: null,        // 本次会话的演示数据\n  api: {},           // svcId -> {ok, loading, data, error, ts}（运行时，不持久化）\n  view: \"overview\",\n  todayOpen: true\n};\nvar pollTimer = null;\n\n/* ---------- 数据层（localStorage 读写，叶子函数） ---------- */\nfunction loadState() {\n  try {\n    var raw = localStorage.getItem(LS_CFG);\n    state.config = raw ? mergeConfig(JSON.parse(raw)) : buildConfigFromEnv();\n  } catch (e) { state.config = buildConfigFromEnv(); }\n  try {\n    var t = localStorage.getItem(LS_TODOS);\n    state.todos = t ? JSON.parse(t) : null;\n  } catch (e) { state.todos = null; }\n  if (!state.todos) {\n    var now = Date.now(), D = 86400e3;\n    state.todos = [\n      { id: uid(), text: \"回复 T-2091 闪退工单\", createdAt: now - 2 * D, done: false },\n      { id: uid(), text: \"审核「动态光影增强 2.1.0」更新包\", createdAt: now - 3 * 3600e3, done: false },\n      { id: uid(), text: \"发布本周博客更新公告\", createdAt: now - 1 * 3600e3, done: false }\n    ];\n    saveTodos();\n  }\n}\n/* 兼容旧配置结构，缺失字段用页面内置配置补齐 */\nfunction mergeConfig(saved) {\n  var base = buildConfigFromEnv();\n  var cfg = Object.assign({}, base, saved || {});\n  cfg.services = base.services.map(function (bs) {\n    var found = null;\n    (saved.services || []).forEach(function (ss) { if (ss.id === bs.id) found = ss; });\n    if (!found) return bs;\n    var svc = Object.assign({}, bs, found);\n    svc.advanced = found.advanced || bs.advanced;\n    /* 迁移：wiki 旧演示映射 → 真实 API 结构（文章列表）；空 API 地址用内置配置补齐 */\n    if (svc.id === \"wiki\") {\n      var wm = svc.advanced && svc.advanced.metrics && svc.advanced.metrics[0];\n      if (wm && wm.path === \"data.stats.pages\") svc.advanced = DEFAULT_MAPPING.wiki;\n      if (!svc.baseUrl && (window.WB_ENV.SERVICES.wiki || {}).API) svc.baseUrl = window.WB_ENV.SERVICES.wiki.API;\n      if (!svc.url && (window.WB_ENV.SERVICES.wiki || {}).URL) svc.url = window.WB_ENV.SERVICES.wiki.URL;\n    }\n    return svc;\n  });\n  if (typeof cfg.demoMode !== \"boolean\") cfg.demoMode = true;\n  cfg.pollMinutes = Number(cfg.pollMinutes) || 0;\n  return cfg;\n}\nfunction saveConfig() { try { localStorage.setItem(LS_CFG, JSON.stringify(state.config)); } catch (e) {} markDirty(); }\nfunction saveTodos() { try { localStorage.setItem(LS_TODOS, JSON.stringify(state.todos)); } catch (e) {} markDirty(); }\nfunction uid() { return Date.now().toString(36) + Math.random().toString(36).slice(2, 7); }\n\n/* ---------- 云同步（GitHub Contents API，仓库即数据库） ---------- */\nfunction syncEnv() {\n  return (window.WB_ENV && window.WB_ENV.SYNC) || { REPO: \"\", BRANCH: \"main\", PATH: \"data/state.json\", AUTO: false };\n}\nfunction syncToken() {\n  try { return localStorage.getItem(LS_SYNC_TOKEN) || \"\"; } catch (e) { return \"\"; }\n}\nfunction syncAutoOn() {\n  try {\n    var v = localStorage.getItem(LS_SYNC_AUTO);\n    if (v === null) return !!syncEnv().AUTO;\n    return v === \"1\";\n  } catch (e) { return false; }\n}\nfunction syncTokensOn() {\n  try { return localStorage.getItem(LS_SYNC_TOKENS) === \"1\"; } catch (e) { return false; }\n}\nfunction syncReady() { return !!(syncEnv().REPO && syncToken()); }\nfunction setSyncStatus(text) {\n  var el = document.getElementById(\"syncStatus\");\n  if (el) {\n    el.textContent = text + \"（\" + fmtTime(Date.now()) + \"）\";\n    try { localStorage.setItem(LS_LAST_SYNC, text); } catch (e) {}\n  }\n}\nfunction syncApiUrl() {\n  var s = syncEnv();\n  return \"https://api.github.com/repos/\" + s.REPO + \"/contents/\" + s.PATH + \"?ref=\" + s.BRANCH;\n}\nfunction b64Utf8Encode(str) { return btoa(utf8(str)); }\nfunction b64Utf8Decode(b64) {\n  try { return decodeURIComponent(escape(atob(String(b64).replace(/\\n/g, \"\")))); }\n  catch (e) { return atob(String(b64).replace(/\\n/g, \"\")); }\n}\nfunction syncHeaders(extra) {\n  var h = { \"Accept\": \"application/vnd.github+json\", \"Content-Type\": \"application/json\" };\n  h[\"Authorization\"] = \"Bearer \" + syncToken();\n  if (extra) { for (var k in extra) h[k] = extra[k]; }\n  return h;\n}\n/* 云端数据文件 → 本地存储的 JSON（content base64 / sha） */\nfunction fetchCloud() {\n  return fetch(syncApiUrl(), { headers: syncHeaders() }).then(function (res) {\n    if (res.status === 404) return { exists: false };\n    if (!res.ok) throw new Error(\"HTTP \" + res.status + (res.status === 401 ? \"（Token 无效或无权限）\" : res.status === 403 ? \"（权限不足或触发限流）\" : \"\"));\n    return res.json().then(function (j) { return { exists: true, sha: j.sha, json: JSON.parse(b64Utf8Decode(j.content)) }; });\n  });\n}\n/* 上传本地状态到云端（剥离敏感字段除非开启） */\nfunction buildSyncPayload() {\n  var cfg = JSON.parse(JSON.stringify(state.config));\n  if (!syncTokensOn()) cfg.services.forEach(function (s) { s.token = \"\"; });\n  return { type: \"wb-hub-cloud\", version: 3, savedAt: new Date().toISOString(), config: cfg, todos: state.todos };\n}\nfunction pushRemote(silent) {\n  if (!syncEnv().REPO) return Promise.resolve(false);\n  if (!syncToken()) {\n    if (!silent) showToast(\"请先在「设置 → 云同步」填写 GitHub Token\", \"err\");\n    return Promise.resolve(false);\n  }\n  setSyncStatus(\"上传中…\");\n  return fetchCloud().then(function (c) {\n    var body = {\n      message: \"sync: 工作台数据更新\",\n      branch: syncEnv().BRANCH,\n      content: b64Utf8Encode(JSON.stringify(buildSyncPayload(), null, 2))\n    };\n    if (c.exists) body.sha = c.sha;\n    return fetch(syncApiUrl(), { method: \"PUT\", headers: syncHeaders(), body: JSON.stringify(body) });\n  }).then(function (res) {\n    if (!res.ok) throw new Error(\"HTTP \" + res.status + (res.status === 409 ? \"（文件冲突，请重试）\" : res.status === 401 ? \"（Token 无效或无权限）\" : \"\"));\n    setSyncStatus(\"已上传到云端 ✓\");\n    if (!silent) showToast(\"已上传到云端\", \"good\");\n    return true;\n  }).catch(function (err) {\n    setSyncStatus(\"上传失败：\" + err.message);\n    if (!silent) showToast(\"上传失败：\" + err.message, \"err\");\n    return false;\n  });\n}\n/* 用云端数据合并到本地：配置覆盖（Token 保留本地值，除非开启同步），待办按 id 合并 */\nfunction applyCloud(cloud) {\n  if (!cloud || typeof cloud !== \"object\") return false;\n  var changed = false;\n  if (cloud.config && typeof cloud.config === \"object\") {\n    var c = cloud.config;\n    if (c.brand) { state.config.brand = c.brand; changed = true; }\n    if (typeof c.demoMode === \"boolean\") { state.config.demoMode = c.demoMode; changed = true; }\n    if (c.pollMinutes !== undefined) { state.config.pollMinutes = Number(c.pollMinutes) || 0; changed = true; }\n    var keepDemo = state.config.demoMode;\n    (c.services || []).forEach(function (cs) {\n      state.config.services.forEach(function (ls) {\n        if (ls.id !== cs.id) return;\n        [\"name\", \"url\", \"baseUrl\", \"authType\", \"headerName\"].forEach(function (k) {\n          if (cs[k] !== undefined && cs[k] !== \"\") ls[k] = cs[k];\n        });\n        if (syncTokensOn() && cs.token) ls.token = cs.token;\n        if (cs.advanced && (cs.advanced.metrics || cs.advanced.list || cs.advanced.todo)) ls.advanced = cs.advanced;\n        if (cs.enabled !== undefined) ls.enabled = cs.enabled;\n      });\n    });\n    state.config.demoMode = keepDemo;\n    if (typeof c.demoMode === \"boolean\") state.config.demoMode = c.demoMode;\n  }\n  if (Array.isArray(cloud.todos)) {\n    var ids = {};\n    state.todos.forEach(function (t) { ids[t.id] = true; });\n    cloud.todos.forEach(function (t) {\n      if (t && t.id && !ids[t.id]) { state.todos.push(t); ids[t.id] = true; changed = true; }\n    });\n  }\n  if (changed) {\n    applyingRemote = true;\n    saveConfig(); saveTodos();\n    applyingRemote = false;\n    refreshAll();\n  }\n  return changed;\n}\n/* 从云端拉取合并（silent=启动时自动，无弹窗） */\nfunction pullRemote(opts) {\n  opts = opts || {};\n  if (!syncEnv().REPO) return Promise.resolve(false);\n  if (!syncToken()) {\n    if (!opts.silent) showToast(\"请先在「设置 → 云同步」填写 GitHub Token\", \"err\");\n    return Promise.resolve(false);\n  }\n  setSyncStatus(opts.silent ? \"正在从云端同步…\" : \"拉取中…\");\n  return fetchCloud().then(function (c) {\n    if (!c.exists) {\n      setSyncStatus(\"云端暂无数据，可点「上传到云端」创建\");\n      if (!opts.silent) showToast(\"云端暂无数据\");\n      return false;\n    }\n    if (!opts.silent) {\n      return new Promise(function (resolve) {\n        confirmDialog(\"从云端恢复\", \"将用云端数据覆盖本地的品牌名/服务配置/映射，并把云端待办合并进来（本设备 Token 不受影响）。继续吗？\", function () {\n          resolve(applyCloud(c.json));\n        }, function () { resolve(false); });\n      }).then(function (ok) {\n        if (ok) { setSyncStatus(\"已从云端恢复 ✓\"); showToast(\"已从云端恢复\", \"good\"); }\n        return ok;\n      });\n    }\n    var changed = applyCloud(c.json);\n    setSyncStatus(changed ? \"已自动同步云端数据 ✓\" : \"云端已是最新 ✓\");\n    return changed;\n  }).catch(function (err) {\n    setSyncStatus(\"同步失败：\" + err.message);\n    if (!opts.silent) showToast(\"拉取失败：\" + err.message, \"err\");\n    return false;\n  });\n}\n/* 本地变更 → 后端模式防抖推 D1 / 本地模式防抖推 GitHub */\nvar dirtyTimer = null, serverDirtyTimer = null, applyingRemote = false;\nfunction markDirty() {\n  if (applyingRemote) return;\n  if (RUNTIME.mode === \"server\") {\n    if (!sessionToken()) return;\n    if (serverDirtyTimer) clearTimeout(serverDirtyTimer);\n    serverDirtyTimer = setTimeout(function () { pushServerState(true); }, 800);\n    return;\n  }\n  if (!syncAutoOn() || !syncReady()) return;\n  if (dirtyTimer) clearTimeout(dirtyTimer);\n  setSyncStatus(\"有未上传的本地变更…\");\n  dirtyTimer = setTimeout(function () { pushRemote(true); }, 5000);\n}\n\n/* ---------- 计算层（只读，无渲染、无副作用） ---------- */\nfunction getPath(obj, path) {\n  if (!path || typeof path !== \"string\") return undefined;\n  var parts = path.replace(/\\[(\\d+)\\]/g, \".$1\").split(\".\").filter(Boolean);\n  var cur = obj;\n  for (var i = 0; i < parts.length; i++) {\n    if (cur == null) return undefined;\n    cur = cur[parts[i]];\n  }\n  return cur;\n}\nfunction fmtNum(v) {\n  if (v === undefined || v === null || v === \"\") return \"—\";\n  if (typeof v === \"number\") {\n    if (isNaN(v)) return \"—\";\n    return v >= 100000 ? (v / 10000).toFixed(1).replace(/\\.0$/, \"\") + \"w\" : v.toLocaleString(\"zh-CN\");\n  }\n  return String(v);\n}\nfunction fmtTime(v) {\n  if (v === undefined || v === null || v === \"\") return \"—\";\n  var d = new Date(typeof v === \"number\" ? v : String(v));\n  if (isNaN(d.getTime())) return String(v);\n  var p = function (n) { return n < 10 ? \"0\" + n : \"\" + n; };\n  return (d.getMonth() + 1) + \"月\" + d.getDate() + \"日 \" + p(d.getHours()) + \":\" + p(d.getMinutes());\n}\nfunction startOfToday() { var d = new Date(); d.setHours(0, 0, 0, 0); return d.getTime(); }\nfunction getApiData(svc) {\n  var c = state.api[svc.id];\n  if (c && c.ok) return { data: c.data, source: \"api\" };\n  if (state.config.demoMode) return { data: state.demo[svc.id], source: \"demo\" };\n  return null;\n}\nfunction computeStatus(svc) {\n  var c = state.api[svc.id];\n  if (c && c.loading) return \"loading\";\n  if (svc.baseUrl && c && c.ok) return \"ok\";\n  if (svc.baseUrl && c && !c.ok) return state.config.demoMode ? \"demo\" : \"error\";\n  return state.config.demoMode ? \"demo\" : \"idle\";\n}\nvar STATUS_TEXT = { ok: \"已连接\", demo: \"演示数据\", error: \"连接失败\", idle: \"未接入\", loading: \"同步中\" };\nfunction badgeFor(v) {\n  var map = {\n    \"critical\": \"b-red\", \"严重\": \"b-red\", \"高\": \"b-red\", \"紧急\": \"b-red\", \"未处理\": \"b-red\", \"连接失败\": \"b-red\",\n    \"待处理\": \"b-orange\", \"待审核\": \"b-orange\", \"warning\": \"b-orange\", \"中\": \"b-orange\", \"顺延\": \"b-orange\", \"演示数据\": \"b-orange\",\n    \"处理中\": \"b-blue\", \"进行中\": \"b-blue\", \"同步中\": \"b-blue\",\n    \"已完成\": \"b-green\", \"已发布\": \"b-green\", \"已处理\": \"b-green\", \"已解决\": \"b-green\", \"已连接\": \"b-green\",\n    \"未接入\": \"b-gray\"\n  };\n  return map[String(v)] || \"b-gray\";\n}\n\n/* 「今天要处理」聚合：本地待办 + 服务待处理项提取 */\nfunction collectTodayItems() {\n  var items = [], now = Date.now();\n  state.todos.forEach(function (t) {\n    if (t.done) return;\n    var overdue = t.createdAt < startOfToday();\n    items.push({\n      kind: \"todo\", id: t.id,\n      title: t.text,\n      meta: overdue ? \"顺延自 \" + fmtTime(t.createdAt) : \"快速待办 · \" + fmtTime(t.createdAt),\n      level: overdue ? \"warn\" : \"today\"\n    });\n  });\n  state.config.services.forEach(function (svc) {\n    if (!svc.enabled) return;\n    var todo = svc.advanced && svc.advanced.todo;\n    if (!todo || !todo.listPath) return;\n    var src = getApiData(svc);\n    if (!src) return;\n    var list = getPath(src.data, todo.listPath);\n    if (!Array.isArray(list)) return;\n    var pendingVals = String(todo.pendingValue || \"\").split(\",\").map(function (s) { return s.trim(); }).filter(Boolean);\n    var count = 0, shown = 0;\n    list.forEach(function (it) {\n      var st = getPath(it, todo.statusPath);\n      if (st === undefined) return;\n      if (pendingVals.indexOf(String(st)) === -1) return;\n      count++;\n      if (shown >= 6) return;\n      shown++;\n      var dv = todo.datePath ? getPath(it, todo.datePath) : null;\n      var d = dv !== null && dv !== undefined ? new Date(typeof dv === \"number\" ? dv : String(dv)) : null;\n      var valid = d && !isNaN(d.getTime());\n      var overdue = valid && (now - d.getTime()) > 24 * 3600e3;\n      items.push({\n        kind: \"svc\", svcId: svc.id,\n        title: String(getPath(it, todo.titlePath) || \"(未命名)\"),\n        meta: svc.name + \" · \" + String(st) + (valid ? \" · \" + fmtTime(dv) : \"\"),\n        level: overdue ? \"overdue\" : \"today\"\n      });\n    });\n    if (count > 6) {\n      items.push({ kind: \"more\", svcId: svc.id, title: \"还有 \" + (count - 6) + \" 条待处理…\", meta: \"前往「\" + svc.name + \"」查看全部\", level: \"today\" });\n    }\n  });\n  var order = { overdue: 0, warn: 1, today: 2 };\n  items.sort(function (a, b) { return order[a.level] - order[b.level]; });\n  return items;\n}\n\n/* ---------- API 层 ---------- */\nfunction buildHeaders(svc) {\n  var h = {};\n  if (svc.authType === \"bearer\" && svc.token) h[\"Authorization\"] = \"Bearer \" + svc.token;\n  if (svc.authType === \"header\" && svc.token) h[svc.headerName || \"X-API-Key\"] = svc.token;\n  return h;\n}\nfunction callServiceApi(svc) {\n  var ctrl = new AbortController();\n  var timer = setTimeout(function () { ctrl.abort(); }, 10000);\n  var p;\n  if (RUNTIME.mode === \"server\") {\n    /* 后端网关模式：由 Worker 读取 D1 中的服务配置并转发，前端不经手 Token，无 CORS 问题 */\n    p = fetch(\"api/proxy/\" + svc.id, { headers: apiHeaders(), signal: ctrl.signal })\n      .then(function (res) { if (!res.ok) throw new Error(\"HTTP \" + res.status); return res.json(); });\n  } else {\n    p = fetch(svc.baseUrl, { headers: buildHeaders(svc), signal: ctrl.signal })\n      .then(function (res) {\n        if (!res.ok) throw new Error(\"HTTP \" + res.status);\n        return res.json();\n      });\n  }\n  return p.finally(function () { clearTimeout(timer); });\n}\nfunction fetchService(id, silent) {\n  var svc = null;\n  state.config.services.forEach(function (s) { if (s.id === id) svc = s; });\n  if (!svc || !svc.enabled || !svc.baseUrl) return Promise.resolve();\n  state.api[id] = { ok: false, loading: true, ts: Date.now() };\n  if (!silent) refreshAll();\n  return callServiceApi(svc)\n    .then(function (data) { state.api[id] = { ok: true, data: data, ts: Date.now() }; })\n    .catch(function (err) {\n      var msg = (err && err.name === \"AbortError\") ? \"请求超时（10s）\" : (err && err.message) || \"请求失败\";\n      state.api[id] = { ok: false, error: msg + \"（可能为 CORS 拦截或地址/认证有误）\", ts: Date.now() };\n    })\n    .then(function () { refreshAll(); });\n}\nfunction fetchAll(silent) {\n  var jobs = [];\n  state.config.services.forEach(function (s) {\n    if (s.enabled && s.baseUrl) jobs.push(fetchService(s.id, silent));\n  });\n  return Promise.all(jobs);\n}\nfunction setupPoll() {\n  if (pollTimer) { clearInterval(pollTimer); pollTimer = null; }\n  var m = Number(state.config.pollMinutes) || 0;\n  if (m > 0) pollTimer = setInterval(function () { fetchAll(true); }, m * 60000);\n}\n\n/* ---------- 主题 ---------- */\nfunction applyTheme() {\n  var t = \"auto\";\n  try { t = localStorage.getItem(LS_THEME) || \"auto\"; } catch (e) {}\n  var dark = t === \"dark\" || (t === \"auto\" && window.matchMedia && window.matchMedia(\"(prefers-color-scheme: dark)\").matches);\n  document.documentElement.setAttribute(\"data-theme\", dark ? \"dark\" : \"light\");\n  var btn = document.getElementById(\"btnTheme\");\n  if (btn) btn.innerHTML = ic(dark ? \"sun\" : \"moon\");\n  var meta = document.querySelector('meta[name=\"theme-color\"]');\n  if (meta) meta.setAttribute(\"content\", dark ? \"#121a2b\" : \"#ffffff\");\n}\nfunction cycleTheme() {\n  var cur = \"auto\";\n  try { cur = localStorage.getItem(LS_THEME) || \"auto\"; } catch (e) {}\n  var next = cur === \"auto\" ? \"light\" : cur === \"light\" ? \"dark\" : \"auto\";\n  try { localStorage.setItem(LS_THEME, next); } catch (e) {}\n  applyTheme();\n  showToast(\"主题：\" + (next === \"auto\" ? \"跟随系统\" : next === \"light\" ? \"浅色\" : \"深色\"));\n}\n\n/* ---------- 渲染层（叶子：只读 state 与 DOM，互不调用） ---------- */\nvar $ = function (id) { return document.getElementById(id); };\nfunction esc(s) {\n  return String(s === undefined || s === null ? \"\" : s)\n    .replace(/&/g, \"&amp;\").replace(/</g, \"&lt;\").replace(/>/g, \"&gt;\")\n    .replace(/\"/g, \"&quot;\").replace(/'/g, \"&#39;\");\n}\n\nfunction renderBrand() {\n  $(\"brandName\").textContent = state.config.brand || \"聚合工作台\";\n  document.title = state.config.brand || \"聚合工作台\";\n  var m = document.querySelector('meta[name=\"apple-mobile-web-app-title\"]');\n  if (m) m.setAttribute(\"content\", state.config.brand || \"工作台\");\n}\n\nfunction renderNav() {\n  var html = '<button class=\"chip' + (state.view === \"overview\" ? \" active\" : \"\") + '\" data-action=\"goto\" data-view=\"overview\">' + ic(\"hub\", 15) + \"总览</button>\";\n  state.config.services.forEach(function (svc) {\n    if (!svc.enabled) return;\n    html += '<button class=\"chip' + (state.view === svc.id ? \" active\" : \"\") + '\" data-action=\"goto\" data-view=\"' + svc.id + '\">' + ic(svc.icon, 15) + esc(svc.name) + \"</button>\";\n  });\n  $(\"mainNav\").innerHTML = html;\n}\n\nfunction renderHeaderStatus() {\n  var ok = 0, demo = 0, err = 0, idle = 0;\n  state.config.services.forEach(function (svc) {\n    if (!svc.enabled) return;\n    var st = computeStatus(svc);\n    if (st === \"ok\") ok++;\n    else if (st === \"demo\") demo++;\n    else if (st === \"error\") err++;\n    else idle++;\n  });\n  var parts = [];\n  if (ok) parts.push(ok + \" 在线\");\n  if (demo) parts.push(demo + \" 演示\");\n  if (err) parts.push(err + \" 失败\");\n  if (idle) parts.push(idle + \" 未接入\");\n  var dotCls = err ? \"error\" : ok ? \"ok\" : demo ? \"demo\" : \"idle\";\n  $(\"globalStatus\").innerHTML = '<span class=\"dot ' + dotCls + '\"></span>' + esc(parts.join(\" · \") || \"无服务\");\n}\n\nfunction renderBanner() {\n  var show = false;\n  if (state.config.demoMode && !state.config.bannerClosed) {\n    state.config.services.forEach(function (svc) {\n      if (svc.enabled && (!svc.baseUrl || (state.api[svc.id] && !state.api[svc.id].ok && !state.api[svc.id].loading))) show = true;\n    });\n  }\n  $(\"demoBanner\").classList.toggle(\"hidden\", !show);\n}\n\nfunction renderToday() {\n  var items = collectTodayItems();\n  var openCount = items.filter(function (i) { return i.kind !== \"more\"; }).length;\n  var pill = $(\"todayCount\");\n  pill.textContent = String(openCount);\n  pill.classList.toggle(\"zero\", openCount === 0);\n  $(\"todaySection\").classList.toggle(\"closed\", !state.todayOpen);\n  $(\"todayBody\").classList.toggle(\"hidden\", !state.todayOpen);\n\n  var html = \"\";\n  if (!items.length) {\n    html = '<div class=\"empty\">' + ic(\"check\", 42) + '<div>今日无待办，一切尽在掌握</div></div>';\n  } else {\n    items.forEach(function (it) {\n      var actions = \"\";\n      if (it.kind === \"todo\") {\n        actions = '<button class=\"btn small\" data-action=\"done-todo\" data-id=\"' + it.id + '\" title=\"标记完成\">' + ic(\"check\", 14) + \"完成</button>\" +\n                  '<button class=\"btn small ghost\" data-action=\"del-todo\" data-id=\"' + it.id + '\" title=\"删除\">' + ic(\"x\", 14) + \"</button>\";\n      } else {\n        actions = '<button class=\"btn small\" data-action=\"goto\" data-view=\"' + it.svcId + '\">去处理' + ic(\"chevron\", 14) + \"</button>\";\n      }\n      html += '<div class=\"t-item ' + it.level + '\"><span class=\"t-dot\"></span>' +\n        '<div class=\"t-main\"><div class=\"t-title\">' + esc(it.title) + '</div><div class=\"t-meta\">' + esc(it.meta) + \"</div></div>\" +\n        '<div class=\"t-actions\">' + actions + \"</div></div>\";\n    });\n  }\n  $(\"todayList\").innerHTML = html;\n}\n\nfunction renderOverview() {\n  var enabled = state.config.services.filter(function (s) { return s.enabled; });\n  if (!enabled.length) {\n    $(\"viewOverview\").innerHTML = '<div class=\"sec-title\">' + ic(\"hub\", 17) + \"服务总览</div>\" +\n      '<div class=\"card\" style=\"padding:36px 20px;text-align:center;color:var(--text2)\">' + ic(\"gear\", 36) +\n      '<div style=\"margin-top:10px;font-weight:700;color:var(--text)\">所有服务均已停用</div>' +\n      '<div style=\"font-size:13px;margin-top:4px\">前往设置重新启用你需要的服务</div>' +\n      '<button class=\"btn primary\" style=\"margin-top:15px\" data-action=\"open-settings\">打开设置</button></div>';\n    $(\"viewOverview\").classList.remove(\"hidden\");\n    return;\n  }\n  var html = '<div class=\"sec-title\">' + ic(\"hub\", 17) + '服务总览<span class=\"sub\">点击卡片进入详情</span></div><div class=\"ov-grid\">';\n  state.config.services.forEach(function (svc) {\n    if (!svc.enabled) return;\n    var st = computeStatus(svc);\n    var src = getApiData(svc);\n    var metricsHtml = \"\";\n    var mets = (svc.advanced && svc.advanced.metrics) || [];\n    for (var i = 0; i < 3; i++) {\n      var m = mets[i];\n      if (!m) { metricsHtml += '<div class=\"ov-metric\"><div class=\"v\">—</div><div class=\"l\">&nbsp;</div></div>'; continue; }\n      var v = src ? getPath(src.data, m.path) : undefined;\n      metricsHtml += '<div class=\"ov-metric\"><div class=\"v\">' + esc(fmtNum(v)) + (m.unit ? '<span class=\"u\">' + esc(m.unit) + \"</span>\" : \"\") +\n        '</div><div class=\"l\">' + esc(m.label) + \"</div></div>\";\n    }\n    var linkBtn = svc.url\n      ? '<a class=\"btn small\" href=\"' + esc(svc.url) + '\" target=\"_blank\" rel=\"noopener\" onclick=\"event.stopPropagation()\">' + ic(\"out\", 14) + \"打开</a>\"\n      : \"\";\n    html += '<div class=\"card ov-card svc-c-' + svc.id + '\" data-action=\"goto\" data-view=\"' + svc.id + '\">' +\n      '<div class=\"ov-head\"><span class=\"ov-ico\">' + ic(svc.icon) + '</span><h3>' + esc(svc.name) + \"</h3>\" +\n      '<span class=\"dot ' + st + '\" title=\"' + STATUS_TEXT[st] + '\"></span></div>' +\n      '<div class=\"ov-metrics\">' + metricsHtml + \"</div>\" +\n      '<div class=\"ov-foot\"><span class=\"badge ' + badgeFor(STATUS_TEXT[st]) + '\">' + STATUS_TEXT[st] + \"</span>\" + linkBtn +\n      '<span class=\"arrow\">' + ic(\"chevron\", 16) + \"</span></div></div>\";\n  });\n  html += \"</div>\";\n  $(\"viewOverview\").innerHTML = html;\n  $(\"viewOverview\").classList.toggle(\"hidden\", state.view !== \"overview\");\n}\n\nfunction renderService() {\n  var box = $(\"viewService\");\n  var svc = null;\n  state.config.services.forEach(function (s) { if (s.id === state.view) svc = s; });\n  if (!svc) { box.innerHTML = \"\"; box.classList.add(\"hidden\"); return; }\n  box.classList.remove(\"hidden\");\n\n  var st = computeStatus(svc);\n  var src = getApiData(svc);\n  var loading = state.api[svc.id] && state.api[svc.id].loading;\n\n  var head = '<div class=\"svc-head svc-c-' + svc.id + '\"><span class=\"ov-ico\">' + ic(svc.icon) + \"</span><h2>\" + esc(svc.name) + \"</h2>\" +\n    '<span class=\"badge ' + badgeFor(STATUS_TEXT[st]) + '\">' + STATUS_TEXT[st] + \"</span>\" +\n    '<span class=\"grow\"></span>' +\n    (svc.url ? '<a class=\"btn small\" href=\"' + esc(svc.url) + '\" target=\"_blank\" rel=\"noopener\">' + ic(\"out\", 14) + \"打开服务</a>\" : \"\") +\n    '<button class=\"btn small\" data-action=\"svc-refresh\" data-svc=\"' + svc.id + '\">' + ic(\"refresh\", 14) + \"刷新</button>\" +\n    '<button class=\"btn small ghost\" data-action=\"open-settings\">' + ic(\"gear\", 14) + \"配置</button>\" +\n    (svc.desc ? '<div class=\"desc\">' + esc(svc.desc) + \"</div>\" : \"\") + \"</div>\";\n\n  var body = \"\";\n  if (state.api[svc.id] && !state.api[svc.id].ok && !state.api[svc.id].loading && svc.baseUrl && !state.config.demoMode) {\n    body += '<div class=\"err-box\">' + ic(\"errors\", 16) + \"<span>API 请求失败：\" + esc(state.api[svc.id].error || \"\") + \"</span>\" +\n      '<button class=\"btn\" data-action=\"svc-refresh\" data-svc=\"' + svc.id + '\">重试</button>' +\n      '<button class=\"btn ghost\" data-action=\"open-settings\">检查配置</button></div>';\n  }\n  if (loading) {\n    body += '<div class=\"metric-grid\">' + '<div class=\"card metric-card\"><div class=\"v\">…</div><div class=\"l\">正在同步</div></div></div>';\n  } else if (!src) {\n    body += '<div class=\"card\" style=\"padding:38px 20px;text-align:center;color:var(--text2)\">' + ic(\"gear\", 36) +\n      '<div style=\"margin-top:10px;font-weight:700;color:var(--text)\">尚未接入 API</div>' +\n      '<div style=\"font-size:13px;margin-top:4px\">在设置中填入该服务的 API 地址与 Token，即可在此展示真实数据</div>' +\n      '<button class=\"btn primary\" style=\"margin-top:15px\" data-action=\"open-settings\">去接入</button></div>';\n  } else {\n    var mets = (svc.advanced && svc.advanced.metrics) || [];\n    if (mets.length) {\n      body += '<div class=\"metric-grid\">';\n      mets.forEach(function (m) {\n        var v = getPath(src.data, m.path);\n        var warn = /未处理|逾期|待处理|待审核|严重|失败/.test(m.label || \"\") && typeof v === \"number\" && v > 0;\n        body += '<div class=\"card metric-card' + (warn ? \" warn\" : \"\") + '\"><div class=\"v\">' + esc(fmtNum(v)) +\n          (m.unit ? '<span class=\"u\">' + esc(m.unit) + \"</span>\" : \"\") + '</div><div class=\"l\">' + esc(m.label) + \"</div></div>\";\n      });\n      body += \"</div>\";\n    }\n    var list = svc.advanced && svc.advanced.list;\n    var rows = list ? getPath(src.data, list.path) : null;\n    if (Array.isArray(rows) && rows.length && list.columns && list.columns.length) {\n      var t = \"<table><thead><tr>\";\n      list.columns.forEach(function (c) { t += \"<th>\" + esc(c.title) + \"</th>\"; });\n      t += \"</tr></thead><tbody>\";\n      rows.slice(0, 50).forEach(function (row) {\n        t += \"<tr>\";\n        list.columns.forEach(function (c) {\n          var v = getPath(row, c.path);\n          var lab = ' data-label=\"' + esc(c.title) + '\"';\n          var cell;\n          if (c.format === \"num\") cell = '<td class=\"num\"' + lab + \">\" + esc(fmtNum(v)) + \"</td>\";\n          else if (c.format === \"badge\") { var bv = Array.isArray(v) ? v.join(\"、\") : v; cell = \"<td\" + lab + '><span class=\"badge ' + badgeFor(bv) + '\">' + esc(bv === undefined || bv === null || bv === \"\" ? \"—\" : bv) + \"</span></td>\"; }\n          else if (c.format === \"time\") cell = \"<td\" + lab + \">\" + esc(fmtTime(v)) + \"</td>\";\n          else cell = \"<td\" + lab + \">\" + esc(v === undefined || v === null || v === \"\" ? \"—\" : v) + \"</td>\";\n          t += cell;\n        });\n        t += \"</tr>\";\n      });\n      t += \"</tbody></table>\";\n      body += '<div class=\"tbl-wrap card\">' + t +\n        (rows.length > 50 ? '<div class=\"note\">仅显示前 50 条，共 ' + rows.length + \" 条</div>\" : \"\") +\n        (src.source === \"demo\" ? '<div class=\"note\">当前为演示数据 · 接入真实 API 后自动替换</div>' : \"\") +\n        \"</div>\";\n    } else {\n      body += '<div class=\"card\" style=\"padding:28px;text-align:center;color:var(--text2)\">' +\n        (src.source === \"demo\" ? \"演示数据为空\" : \"未取到列表数据\") +\n        '<div style=\"font-size:12px;margin-top:4px\">请检查映射中 list.path 是否指向数组字段</div></div>';\n    }\n  }\n  box.innerHTML = head + body;\n}\n\n/* 统一刷新入口：只调渲染函数，渲染函数之间禁止互调 */\nfunction refreshAll() {\n  renderBrand();\n  renderNav();\n  renderHeaderStatus();\n  renderBanner();\n  renderToday();\n  renderOverview();\n  renderService();\n}\n\n/* ---------- 设置面板 ---------- */\nfunction fillSettings() {\n  $(\"cfgBrand\").value = state.config.brand || \"\";\n  $(\"cfgDemo\").checked = !!state.config.demoMode;\n  $(\"cfgPoll\").value = String(state.config.pollMinutes || 0);\n  var rb = $(\"runtimeBadge\");\n  if (RUNTIME.mode === \"server\") {\n    rb.className = \"runtime-badge server\";\n    rb.innerHTML = '<span class=\"rdot\"></span>云端后端模式（CF Worker + D1）· 数据自动同步 · API 网关集中调用';\n  } else {\n    rb.className = \"runtime-badge\";\n    rb.innerHTML = '<span class=\"rdot\"></span>本地模式 · 数据存本机浏览器（部署到 Cloudflare Worker 可启用 D1 云端）';\n  }\n  /* 云同步区块 */\n  var sEnv = syncEnv();\n  $(\"syncRepoName\").textContent = sEnv.REPO || \"(未配置仓库)\";\n  $(\"syncTarget\").textContent = sEnv.REPO ? sEnv.REPO + \" @ \" + sEnv.BRANCH + \" : \" + sEnv.PATH : \"未配置（在页面文件 WB_ENV.SYNC 中设置）\";\n  $(\"syncToken\").value = syncToken();\n  $(\"syncAuto\").checked = syncAutoOn();\n  $(\"syncTokens\").checked = syncTokensOn();\n  var last = null;\n  try { last = localStorage.getItem(LS_LAST_SYNC); } catch (e) {}\n  $(\"syncStatus\").textContent = syncToken() ? (last || \"就绪，可手动上传/恢复\") : \"未填写 Token，云同步未启用\";\n  var html = \"\";\n  SVC_DEFS.forEach(function (def) {\n    var svc = null;\n    state.config.services.forEach(function (s) { if (s.id === def.id) svc = s; });\n    if (!svc) return;\n    var st = computeStatus(svc);\n    html += '<details class=\"svc-block svc-c-' + def.id + '\" data-svc=\"' + def.id + '\">' +\n      \"<summary><span class=\\\"s-ico\\\">\" + ic(def.icon, 15) + \"</span>\" + esc(svc.name) + '<span class=\"tag badge ' + badgeFor(STATUS_TEXT[st]) + '\">' + STATUS_TEXT[st] + \"</span></summary>\" +\n      '<div class=\"svc-form\">' +\n      '<label class=\"chk\"><input type=\"checkbox\" class=\"f-enabled\"' + (svc.enabled ? \" checked\" : \"\") + \"> 启用该服务</label>\" +\n      '<div class=\"grid2\">' +\n      '<div class=\"form-row\"><label>显示名称</label><input type=\"text\" class=\"f-name\" value=\"' + esc(svc.name) + '\"></div>' +\n      '<div class=\"form-row\"><label>服务地址（前端，用于跳转）</label><input type=\"text\" class=\"f-url\" value=\"' + esc(svc.url) + '\" placeholder=\"https://dl.example.com\"></div>' +\n      \"</div>\" +\n      '<div class=\"form-row\"><label>API 地址（返回 JSON）</label><input type=\"text\" class=\"f-api\" value=\"' + esc(svc.baseUrl) + '\" placeholder=\"https://dl.example.com/api/stats\"></div>' +\n      '<div class=\"grid3\">' +\n      '<div class=\"form-row\"><label>认证方式</label><select class=\"f-auth\">' +\n      '<option value=\"none\"' + (svc.authType === \"none\" ? \" selected\" : \"\") + \">无需认证</option>\" +\n      '<option value=\"bearer\"' + (svc.authType === \"bearer\" ? \" selected\" : \"\") + \">Bearer Token</option>\" +\n      '<option value=\"header\"' + (svc.authType === \"header\" ? \" selected\" : \"\") + \">自定义 Header</option>\" +\n      \"</select></div>\" +\n      '<div class=\"form-row\"><label>Token / Key</label><input type=\"text\" class=\"f-token\" value=\"' + esc(svc.token) + '\" placeholder=\"留空则不发送\"></div>' +\n      '<div class=\"form-row\"><label>Header 名（自定义时）</label><input type=\"text\" class=\"f-header\" value=\"' + esc(svc.headerName) + '\" placeholder=\"X-API-Key\"></div>' +\n      \"</div>\" +\n      '<div class=\"form-row\"><label>数据映射 JSON（metrics 指标 / list 列表 / todo 待处理提取）</label>' +\n      '<textarea class=\"f-mapping\" rows=\"12\" spellcheck=\"false\">' + esc(JSON.stringify(svc.advanced || {}, null, 2)) + \"</textarea></div>\" +\n      '<div class=\"btn-row\">' +\n      '<button class=\"btn small\" data-action=\"test-conn\" data-svc=\"' + def.id + '\">' + ic(\"refresh\", 14) + \"测试连接</button>\" +\n      '<button class=\"btn small ghost\" data-action=\"reset-mapping\" data-svc=\"' + def.id + '\">恢复默认映射</button>' +\n      \"</div>\" +\n      '<pre class=\"test-result hidden\"></pre>' +\n      \"</div></details>\";\n  });\n  $(\"svcForms\").innerHTML = html;\n}\nfunction collectSvcFromForm(block, defId) {\n  var svc = null;\n  state.config.services.forEach(function (s) { if (s.id === defId) svc = s; });\n  if (!svc) return null;\n  var next = Object.assign({}, svc);\n  next.enabled = block.querySelector(\".f-enabled\").checked;\n  next.name = block.querySelector(\".f-name\").value.trim() || svc.name;\n  next.url = block.querySelector(\".f-url\").value.trim();\n  next.baseUrl = block.querySelector(\".f-api\").value.trim();\n  next.authType = block.querySelector(\".f-auth\").value;\n  next.token = block.querySelector(\".f-token\").value.trim();\n  next.headerName = block.querySelector(\".f-header\").value.trim() || \"X-API-Key\";\n  var raw = block.querySelector(\".f-mapping\").value;\n  var parsed = JSON.parse(raw); // 交给调用方 try/catch\n  if (typeof parsed !== \"object\" || parsed === null || Array.isArray(parsed)) throw new Error(defId + \" 的映射必须是 JSON 对象\");\n  if (parsed.metrics && !Array.isArray(parsed.metrics)) throw new Error(defId + \" 的 metrics 必须是数组\");\n  next.advanced = parsed;\n  return next;\n}\nfunction saveSettingsFromForm() {\n  var brand = $(\"cfgBrand\").value.trim() || \"聚合工作台\";\n  var demoMode = $(\"cfgDemo\").checked;\n  var poll = Math.max(0, parseInt($(\"cfgPoll\").value, 10) || 0);\n  /* 云同步设置（Token/开关存本设备） */\n  try {\n    localStorage.setItem(LS_SYNC_TOKEN, $(\"syncToken\").value.trim());\n    localStorage.setItem(LS_SYNC_AUTO, $(\"syncAuto\").checked ? \"1\" : \"0\");\n    localStorage.setItem(LS_SYNC_TOKENS, $(\"syncTokens\").checked ? \"1\" : \"0\");\n  } catch (e) {}\n  var services = [];\n  var blocks = document.querySelectorAll(\"#svcForms .svc-block\");\n  for (var i = 0; i < blocks.length; i++) {\n    var block = blocks[i];\n    var sid = block.getAttribute(\"data-svc\");\n    var svc = collectSvcFromForm(block, sid);\n    if (!svc) continue;\n    services.push(svc);\n  }\n  if (services.length !== state.config.services.length) throw new Error(\"服务配置数量异常，请刷新页面重试\");\n  state.config.brand = brand;\n  state.config.demoMode = demoMode;\n  state.config.pollMinutes = poll;\n  state.config.services = services;\n  saveConfig();\n  setupPoll();\n}\n/* 用页面 WB_ENV 内置配置覆盖本设备设置 */\nfunction applyEnvConfig() {\n  var envCfg = buildConfigFromEnv();\n  state.config.brand = envCfg.brand;\n  state.config.demoMode = envCfg.demoMode;\n  state.config.pollMinutes = envCfg.pollMinutes;\n  state.config.services = state.config.services.map(function (svc, i) {\n    var e = envCfg.services[i];\n    return Object.assign({}, svc, {\n      name: e.name, url: e.url, baseUrl: e.baseUrl,\n      authType: e.authType, token: e.token, headerName: e.headerName\n    });\n  });\n  saveConfig();\n  setupPoll();\n  fillSettings();\n  refreshAll();\n  fetchAll();\n  showToast(\"已应用页面内置 API 配置\", \"good\");\n}\n\nfunction testConnection(defId) {\n  var block = document.querySelector('#svcForms .svc-block[data-svc=\"' + defId + '\"]');\n  var pre = block.querySelector(\".test-result\");\n  pre.classList.remove(\"hidden\", \"good\", \"bad\");\n  var svc;\n  try { svc = collectSvcFromForm(block, defId); }\n  catch (e) {\n    pre.textContent = \"映射 JSON 有误：\" + e.message;\n    pre.classList.add(\"bad\");\n    return;\n  }\n  if (!svc.baseUrl) {\n    pre.textContent = \"请先填写 API 地址\";\n    pre.classList.add(\"bad\");\n    return;\n  }\n  pre.textContent = \"请求中…\" + svc.baseUrl;\n  if (RUNTIME.mode === \"server\") {\n    pre.textContent = \"请求中（经后端网关代理）…\";\n    fetch(\"api/proxy-test\", { method: \"POST\", headers: apiHeaders(), body: JSON.stringify({ service: { baseUrl: svc.baseUrl, authType: svc.authType, token: svc.token, headerName: svc.headerName } }) })\n      .then(function (r) { if (!r.ok) throw new Error(\"HTTP \" + r.status); return r.json(); })\n      .then(function (data) {\n        var top = (data && typeof data === \"object\") ? \"顶层字段：\" + Object.keys(data).join(\", \") + \"\\n\\n\" : \"\";\n        var body = JSON.stringify(data, null, 2);\n        pre.textContent = \"✓ 连接成功（经 D1 网关）\\n\" + top + body.slice(0, 1200) + (body.length > 1200 ? \"\\n…（已截断）\" : \"\");\n        pre.classList.add(\"good\");\n      })\n      .catch(function (err) {\n        pre.textContent = \"✗ 失败：\" + ((err && err.name === \"AbortError\") ? \"请求超时（10s）\" : (err && err.message) || \"未知错误\") +\n          \"\\n提示：保存设置后，后端会自动把该服务配置写入 D1，之后用 api/proxy/<服务> 即可集中调用。\";\n        pre.classList.add(\"bad\");\n      });\n    return;\n  }\n  callServiceApi(svc)\n    .then(function (data) {\n      var top = (data && typeof data === \"object\") ? \"顶层字段：\" + Object.keys(data).join(\", \") + \"\\n\\n\" : \"\";\n      var body = JSON.stringify(data, null, 2);\n      pre.textContent = \"✓ 连接成功\\n\" + top + body.slice(0, 1200) + (body.length > 1200 ? \"\\n…（已截断）\" : \"\");\n      pre.classList.add(\"good\");\n    })\n    .catch(function (err) {\n      pre.textContent = \"✗ 失败：\" + ((err && err.name === \"AbortError\") ? \"请求超时（10s）\" : (err && err.message) || \"未知错误\") +\n        \"\\n提示：若浏览器控制台出现 CORS 报错，需在 API 服务端开启跨域允许。\";\n      pre.classList.add(\"bad\");\n    });\n}\n\n/* ---------- 备份 / 恢复 / 清空 ---------- */\nfunction exportBackup() {\n  var payload = { version: 1, type: \"wb-hub-backup\", exportedAt: new Date().toISOString(), config: state.config, todos: state.todos };\n  var blob = new Blob([JSON.stringify(payload, null, 2)], { type: \"application/json\" });\n  var a = document.createElement(\"a\");\n  var d = new Date();\n  var p = function (n) { return n < 10 ? \"0\" + n : \"\" + n; };\n  a.href = URL.createObjectURL(blob);\n  a.download = (state.config.brand || \"聚合工作台\") + \"备份-\" + d.getFullYear() + p(d.getMonth() + 1) + p(d.getDate()) + \".json\";\n  document.body.appendChild(a);\n  a.click();\n  setTimeout(function () { URL.revokeObjectURL(a.href); a.remove(); }, 300);\n  showToast(\"备份已导出\", \"good\");\n}\nfunction importBackup(file) {\n  var reader = new FileReader();\n  reader.onload = function () {\n    try {\n      var data = JSON.parse(reader.result);\n      if (!data || (!data.config && !data.todos)) throw new Error(\"不是有效的工作台备份文件\");\n      if (data.config) state.config = mergeConfig(data.config);\n      if (Array.isArray(data.todos)) state.todos = data.todos;\n      saveConfig(); saveTodos();\n      fillSettings();\n      setupPoll();\n      refreshAll();\n      fetchAll();\n      showToast(\"导入成功，配置已恢复\", \"good\");\n    } catch (e) {\n      showToast(\"导入失败：\" + e.message, \"err\");\n    }\n  };\n  reader.onerror = function () { showToast(\"读取文件失败\", \"err\"); };\n  reader.readAsText(file);\n}\nfunction confirmDialog(title, text, onYes, onNo) {\n  $(\"confirmTitle\").textContent = title;\n  $(\"confirmText\").textContent = text;\n  $(\"confirmModal\").classList.remove(\"hidden\");\n  $(\"confirmYes\").onclick = function () { $(\"confirmModal\").classList.add(\"hidden\"); onYes(); };\n  $(\"confirmNo\").onclick = function () { $(\"confirmModal\").classList.add(\"hidden\"); if (onNo) onNo(); };\n}\n\n/* ---------- toast ---------- */\nvar toastTimer = null;\nfunction showToast(msg, type) {\n  var t = $(\"toast\");\n  t.textContent = msg;\n  t.className = type === \"err\" ? \"err\" : type === \"good\" ? \"good\" : \"\";\n  t.classList.add(\"show\");\n  if (toastTimer) clearTimeout(toastTimer);\n  toastTimer = setTimeout(function () { t.classList.remove(\"show\"); }, 2600);\n}\n\n/* ---------- 事件处理（改数据 → refreshAll，禁止渲染函数互相触发） ---------- */\nfunction gotoView(view) {\n  state.view = view;\n  refreshAll();\n  try { window.scrollTo({ top: 0, behavior: \"smooth\" }); } catch (e) { window.scrollTo(0, 0); }\n}\nfunction bindEvents() {\n  $(\"btnRefresh\").innerHTML = ic(\"refresh\");\n  $(\"btnExportTop\").innerHTML = ic(\"export\");\n  $(\"btnSettings\").innerHTML = ic(\"gear\");\n  $(\"btnCloseSettings\").innerHTML = ic(\"x\");\n  $(\"clockIcon\").innerHTML = ic(\"clock\");\n  $(\"todayFoldBtn\").innerHTML = ic(\"chevron\");\n  $(\"brandIcon\").innerHTML = ic(\"hub\", 17);\n  applyTheme();\n\n  $(\"loginForm\").addEventListener(\"submit\", function (e) {\n    e.preventDefault();\n    attemptLogin();\n  });\n  $(\"btnApplyEnv\").addEventListener(\"click\", applyEnvConfig);\n  $(\"btnSyncUp\").addEventListener(\"click\", function () {\n    try { localStorage.setItem(LS_SYNC_TOKEN, $(\"syncToken\").value.trim()); } catch (e) {}\n    pushRemote(false);\n  });\n  $(\"btnSyncDown\").addEventListener(\"click\", function () {\n    try { localStorage.setItem(LS_SYNC_TOKEN, $(\"syncToken\").value.trim()); } catch (e) {}\n    pullRemote({ silent: false });\n  });\n  $(\"syncToken\").addEventListener(\"change\", function () {\n    try { localStorage.setItem(LS_SYNC_TOKEN, this.value.trim()); } catch (e) {}\n  });\n\n  $(\"mainNav\").addEventListener(\"click\", function (e) {\n    var el = e.target.closest(\"[data-action='goto']\");\n    if (el) gotoView(el.getAttribute(\"data-view\"));\n  });\n  $(\"main\").addEventListener(\"click\", function (e) {\n    var el = e.target.closest(\"[data-action]\");\n    if (!el) return;\n    var act = el.getAttribute(\"data-action\");\n    if (act === \"goto\") { gotoView(el.getAttribute(\"data-view\")); return; }\n    if (act === \"done-todo\") {\n      var id = el.getAttribute(\"data-id\");\n      state.todos.forEach(function (t) { if (t.id === id) t.done = true; });\n      saveTodos(); refreshAll(); showToast(\"已完成\");\n      return;\n    }\n    if (act === \"del-todo\") {\n      var did = el.getAttribute(\"data-id\");\n      state.todos = state.todos.filter(function (t) { return t.id !== did; });\n      saveTodos(); refreshAll();\n      return;\n    }\n    if (act === \"svc-refresh\") {\n      var sid = el.getAttribute(\"data-svc\");\n      if (sid) fetchService(sid); else fetchAll();\n      return;\n    }\n    if (act === \"open-settings\") {\n      state.config.bannerClosed = true; saveConfig();\n      fillSettings();\n      $(\"settingsOverlay\").classList.remove(\"hidden\");\n      return;\n    }\n  });\n  $(\"btnTheme\").addEventListener(\"click\", cycleTheme);\n  $(\"btnRefresh\").addEventListener(\"click\", function () {\n    var jobs = state.config.services.filter(function (s) { return s.enabled && s.baseUrl; }).length;\n    if (jobs) { fetchAll(); showToast(\"正在刷新 \" + jobs + \" 个服务…\"); }\n    else { refreshAll(); showToast(\"已刷新（当前为演示数据）\"); }\n  });\n  $(\"btnExportTop\").addEventListener(\"click\", exportBackup);\n  $(\"btnSettings\").addEventListener(\"click\", function () {\n    fillSettings();\n    $(\"settingsOverlay\").classList.remove(\"hidden\");\n  });\n\n  $(\"todaySection\").addEventListener(\"submit\", function (e) {\n    e.preventDefault();\n    var input = $(\"todoInput\");\n    var text = input.value.trim();\n    if (!text) { showToast(\"先输入待办内容\"); return; }\n    state.todos.unshift({ id: uid(), text: text, createdAt: Date.now(), done: false });\n    input.value = \"\";\n    saveTodos(); refreshAll();\n  });\n  $(\"todayFoldBtn\").addEventListener(\"click\", function () {\n    state.todayOpen = !state.todayOpen;\n    refreshAll();\n  });\n\n  $(\"demoBanner\").addEventListener(\"click\", function (e) {\n    var el = e.target.closest(\"[data-action]\");\n    if (!el) return;\n    if (el.getAttribute(\"data-action\") === \"open-settings\") {\n      state.config.bannerClosed = true; saveConfig();\n      fillSettings();\n      $(\"settingsOverlay\").classList.remove(\"hidden\");\n      return;\n    }\n    if (el.getAttribute(\"data-action\") === \"close-banner\") {\n      state.config.bannerClosed = true; saveConfig(); refreshAll();\n    }\n  });\n\n  $(\"settingsOverlay\").addEventListener(\"click\", function (e) {\n    var el = e.target.closest(\"[data-action]\");\n    if (el) {\n      var act = el.getAttribute(\"data-action\");\n      if (act === \"close-settings\") { $(\"settingsOverlay\").classList.add(\"hidden\"); return; }\n      if (act === \"test-conn\") { testConnection(el.getAttribute(\"data-svc\")); return; }\n      if (act === \"reset-mapping\") {\n        var sid = el.getAttribute(\"data-svc\");\n        var block = document.querySelector('#svcForms .svc-block[data-svc=\"' + sid + '\"]');\n        block.querySelector(\".f-mapping\").value = JSON.stringify(DEFAULT_MAPPING[sid], null, 2);\n        showToast(\"已恢复该服务默认映射\");\n        return;\n      }\n    }\n    if (e.target === $(\"settingsOverlay\")) $(\"settingsOverlay\").classList.add(\"hidden\");\n  });\n  $(\"btnSaveSettings\").addEventListener(\"click\", function () {\n    try {\n      saveSettingsFromForm();\n      $(\"settingsOverlay\").classList.add(\"hidden\");\n      refreshAll();\n      fetchAll();\n      showToast(\"设置已保存\", \"good\");\n    } catch (e) {\n      showToast(\"保存失败：\" + e.message, \"err\");\n    }\n  });\n  $(\"btnExport\").addEventListener(\"click\", exportBackup);\n  $(\"btnImport\").addEventListener(\"click\", function () { $(\"importFile\").click(); });\n  $(\"importFile\").addEventListener(\"change\", function () {\n    if (this.files && this.files[0]) importBackup(this.files[0]);\n    this.value = \"\";\n  });\n  $(\"btnWipe\").addEventListener(\"click\", function () {\n    confirmDialog(\"清空全部数据\", \"将删除所有 API 配置、待办与本地数据，且不可恢复。建议先「导出 JSON 备份」。确定继续吗？\", function () {\n      try { localStorage.removeItem(LS_CFG); localStorage.removeItem(LS_TODOS); } catch (e) {}\n      location.reload();\n    });\n  });\n}\n\n/* ---------- 登录门禁 ---------- */\nvar RUNTIME = { mode: \"local\" };      // local=纯本地 | server=云端后端(CF Worker + D1)\nvar SESSION_KEY = \"wb_hub_session\";   // 后端模式会话 Token（服务端 7 天有效）\nfunction sessionToken() {\n  try { return localStorage.getItem(SESSION_KEY) || \"\"; } catch (e) { return \"\"; }\n}\nfunction apiHeaders(extra) {\n  var h = { \"Content-Type\": \"application/json\" };\n  var t = sessionToken();\n  if (t) h[\"Authorization\"] = \"Bearer \" + t;\n  if (extra) { for (var k in extra) h[k] = extra[k]; }\n  return h;\n}\nfunction apiFetch(path, opts) {\n  opts = opts || {};\n  opts.headers = apiHeaders(opts.headers);\n  return fetch(path, opts).then(function (res) {\n    if (res.status === 401) {\n      try { localStorage.removeItem(SESSION_KEY); } catch (e) {}\n      showLogin(\"会话已过期，请重新登录\");\n      throw new Error(\"unauthorized\");\n    }\n    return res;\n  });\n}\nfunction detectMode() {\n  return fetch(\"api/health\", { headers: { \"Accept\": \"application/json\" } })\n    .then(function (r) { return r.ok ? r.json() : null; })\n    .then(function (j) { return (j && j.mode === \"server\") ? \"server\" : \"local\"; })\n    .catch(function () { return \"local\"; });\n}\nfunction isAuthed() {\n  try {\n    var until = Number(localStorage.getItem(LS_AUTH)) || 0;\n    return sessionStorage.getItem(\"wb_hub_auth\") === \"1\" || until > Date.now();\n  } catch (e) { return false; }\n}\nfunction loginFailState() {\n  try { return JSON.parse(localStorage.getItem(LS_FAIL)) || { n: 0, until: 0 }; }\n  catch (e) { return { n: 0, until: 0 }; }\n}\nfunction showLoginError(msg) {\n  var box = $(\"loginError\");\n  box.textContent = msg;\n  box.classList.remove(\"hidden\");\n}\nfunction updateLockUi() {\n  var st = loginFailState();\n  var btn = $(\"loginBtn\");\n  var remain = st.until - Date.now();\n  if (remain > 0) {\n    btn.disabled = true;\n    btn.textContent = \"已锁定 \" + Math.ceil(remain / 1000) + \" 秒\";\n    setTimeout(updateLockUi, 500);\n  } else {\n    btn.disabled = false;\n    btn.textContent = \"登录\";\n    if (st.n >= 5) { try { localStorage.removeItem(LS_FAIL); } catch (e) {} }\n  }\n}\nfunction attemptLogin() {\n  var user = $(\"loginUser\").value.trim();\n  var pass = $(\"loginPass\").value;\n  var env = (window.WB_ENV && window.WB_ENV.LOGIN) || {};\n  var st = loginFailState();\n  if (st.until - Date.now() > 0) { showLoginError(\"尝试次数过多，请稍后再试\"); updateLockUi(); return; }\n  if (user === (env.USER || \"admin\") && pass && passHash(pass) === (env.PASS_SHA256 || \"\")) {\n    try { localStorage.removeItem(LS_FAIL); } catch (e) {}\n    sessionStorage.setItem(\"wb_hub_auth\", \"1\");\n    if ($(\"loginRemember\").checked) {\n      try { localStorage.setItem(LS_AUTH, String(Date.now() + 7 * 86400e3)); } catch (e) {}\n    }\n    $(\"loginGate\").classList.add(\"hidden\");\n    $(\"loginPass\").value = \"\";\n    enterApp();\n  } else {\n    st.n = (st.n || 0) + 1;\n    if (st.n >= 5) { st.until = Date.now() + 30 * 1000; }\n    try { localStorage.setItem(LS_FAIL, JSON.stringify(st)); } catch (e) {}\n    showLoginError(\"账号或密码错误\" + (st.n >= 5 ? \"，已临时锁定 30 秒\" : \"（已失败 \" + st.n + \" 次）\"));\n    if (st.n >= 5) updateLockUi();\n  }\n}\nfunction showLogin(msg) {\n  $(\"loginGate\").classList.remove(\"hidden\");\n  $(\"loginTitle\").textContent = (window.WB_ENV && window.WB_ENV.BRAND) || \"聚合工作台\";\n  var tip = $(\"runtimeTip\");\n  if (tip) tip.textContent = RUNTIME.mode === \"server\" ? \"云端后端模式 · 配置与待办存 D1 数据库\" : \"本地模式 · 数据存本机浏览器\";\n  if (msg) showLoginError(msg); else $(\"loginError\").classList.add(\"hidden\");\n}\nfunction attemptLogin() {\n  var user = $(\"loginUser\").value.trim();\n  var pass = $(\"loginPass\").value;\n  var btn = $(\"loginBtn\");\n  if (RUNTIME.mode === \"server\") {\n    var st = loginFailState();\n    if (st.until - Date.now() > 0) { showLoginError(\"尝试次数过多，请稍后再试\"); updateLockUi(); return; }\n    btn.disabled = true; btn.textContent = \"登录中…\";\n    fetch(\"api/auth/login\", { method: \"POST\", headers: { \"Content-Type\": \"application/json\" }, body: JSON.stringify({ user: user, pass: pass }) })\n      .then(function (r) {\n        if (r.status === 401) throw new Error(\"账号或密码错误\");\n        if (!r.ok) throw new Error(\"HTTP \" + r.status);\n        return r.json();\n      })\n      .then(function (j) {\n        try { localStorage.removeItem(LS_FAIL); } catch (e) {}\n        try { localStorage.setItem(SESSION_KEY, j.token); } catch (e) {}\n        $(\"loginGate\").classList.add(\"hidden\");\n        $(\"loginPass\").value = \"\";\n        enterApp();\n      })\n      .catch(function (err) {\n        st.n = (st.n || 0) + 1;\n        if (st.n >= 5) { st.until = Date.now() + 30 * 1000; }\n        try { localStorage.setItem(LS_FAIL, JSON.stringify(st)); } catch (e) {}\n        showLoginError((err.message || \"登录失败\") + (st.n >= 5 ? \"，已临时锁定 30 秒\" : \"（已失败 \" + st.n + \" 次）\"));\n        if (st.n >= 5) updateLockUi();\n      })\n      .finally(function () { btn.disabled = false; btn.textContent = \"登录\"; });\n    return;\n  }\n  var env = (window.WB_ENV && window.WB_ENV.LOGIN) || {};\n  var st2 = loginFailState();\n  if (st2.until - Date.now() > 0) { showLoginError(\"尝试次数过多，请稍后再试\"); updateLockUi(); return; }\n  if (user === (env.USER || \"admin\") && pass && passHash(pass) === (env.PASS_SHA256 || \"\")) {\n    try { localStorage.removeItem(LS_FAIL); } catch (e) {}\n    sessionStorage.setItem(\"wb_hub_auth\", \"1\");\n    if ($(\"loginRemember\").checked) {\n      try { localStorage.setItem(LS_AUTH, String(Date.now() + 7 * 86400e3)); } catch (e) {}\n    }\n    $(\"loginGate\").classList.add(\"hidden\");\n    $(\"loginPass\").value = \"\";\n    enterApp();\n  } else {\n    st2.n = (st2.n || 0) + 1;\n    if (st2.n >= 5) { st2.until = Date.now() + 30 * 1000; }\n    try { localStorage.setItem(LS_FAIL, JSON.stringify(st2)); } catch (e) {}\n    showLoginError(\"账号或密码错误\" + (st2.n >= 5 ? \"，已临时锁定 30 秒\" : \"（已失败 \" + st2.n + \" 次）\"));\n    if (st2.n >= 5) updateLockUi();\n  }\n}\nfunction boot() {\n  $(\"loginLogo\").innerHTML = ic(\"hub\", 26);\n  bindEvents();\n  applyTheme();\n  detectMode().then(function (mode) {\n    RUNTIME.mode = mode;\n    document.documentElement.setAttribute(\"data-runtime\", mode);\n    if (mode === \"server\") {\n      if (sessionToken()) { $(\"loginGate\").classList.add(\"hidden\"); enterApp(); }\n      else showLogin();\n      return;\n    }\n    if (isAuthed()) {\n      $(\"loginGate\").classList.add(\"hidden\");\n      enterApp();\n    } else {\n      showLogin();\n      updateLockUi();\n      try { sessionStorage.removeItem(\"wb_hub_auth\"); } catch (e) {}\n    }\n  });\n}\nfunction enterApp() {\n  loadState();\n  state.demo = buildDemoData();\n  setupPoll();\n  refreshAll();\n  fetchAll();\n  if (RUNTIME.mode === \"server\") pullServerState();\n  else if (syncAutoOn() && syncReady()) pullRemote({ silent: true });\n}\n\n/* ---------- 后端模式数据流（CF Worker + D1） ---------- */\nfunction pullServerState() {\n  return apiFetch(\"api/state\").then(function (r) { return r.json(); }).then(function (j) {\n    if (!j || j.empty) { pushServerState(true); return; }\n    applyingRemote = true;\n    if (j.config) state.config = mergeConfig(j.config);\n    if (Array.isArray(j.todos)) state.todos = j.todos;\n    applyingRemote = false;\n    saveConfig(); saveTodos();\n    refreshAll();\n    fetchAll();\n  }).catch(function (e) {\n    if (e.message !== \"unauthorized\") showToast(\"云端数据拉取失败：\" + e.message, \"err\");\n  });\n}\nfunction pushServerState(silent) {\n  if (!sessionToken()) return Promise.resolve(false);\n  return apiFetch(\"api/state\", { method: \"PUT\", body: JSON.stringify({ config: state.config, todos: state.todos }) })\n    .then(function (r) { return r.json(); })\n    .then(function (j) {\n      if (!silent) showToast(\"已保存到云端 D1（含各服务 API 配置）\", \"good\");\n      return true;\n    })\n    .catch(function (e) {\n      if (e.message !== \"unauthorized\" && !silent) showToast(\"云端保存失败：\" + e.message, \"err\");\n      return false;\n    });\n}\n\n/* ---------- 初始化 ---------- */\ndocument.addEventListener(\"DOMContentLoaded\", boot);\n</script>\n</body>\n</html>\n";

/* ===================== 后端：API 模块 + D1 数据层 + 集中网关 ===================== */
const LOGIN_CFG = {"USER": "maoxinhe", "SALT": "wb-hub-2026-v1", "PASS_SHA256": "12f0a1de9d4b255513f110f71a7be27f7dcc191e2a0d2f38d1ceb8052a7e050c"};
const JSONH = { "content-type": "application/json;charset=UTF-8" };

function json(data, status) {
  return new Response(JSON.stringify(data), { status: status || 200, headers: { ...JSONH, "cache-control": "no-store" } });
}
async function sha256Hex(s) {
  const buf = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(s));
  return [...new Uint8Array(buf)].map(b => b.toString(16).padStart(2, "0")).join("");
}
let schemaReady = false;
async function ensureSchema(db) {
  if (schemaReady) return;
  await db.batch([
    db.prepare("CREATE TABLE IF NOT EXISTS state (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT NOT NULL)"),
    db.prepare("CREATE TABLE IF NOT EXISTS services (id TEXT PRIMARY KEY, name TEXT, url TEXT, base_url TEXT, auth_type TEXT, token TEXT, header_name TEXT, mapping TEXT, enabled INTEGER DEFAULT 1, updated_at TEXT)"),
    db.prepare("CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, created_at TEXT NOT NULL, expires_at TEXT NOT NULL)")
  ]);
  schemaReady = true;
}
async function getUser(request, db) {
  const m = (request.headers.get("Authorization") || "").match(/^Bearer (.+)$/);
  if (!m) return null;
  const row = await db.prepare("SELECT token FROM sessions WHERE token = ? AND expires_at > ?").bind(m[1], new Date().toISOString()).first();
  return row ? (LOGIN_CFG.USER || "admin") : null;
}
function newToken() {
  const a = new Uint8Array(24);
  crypto.getRandomValues(a);
  return [...a].map(b => b.toString(16).padStart(2, "0")).join("");
}
function timeoutSignal(ms) {
  const ctrl = new AbortController();
  setTimeout(() => ctrl.abort(), ms);
  return ctrl.signal;
}

/* ---- 登录 / 会话 ---- */
async function handleLogin(request, db) {
  let body;
  try { body = await request.json(); } catch (e) { return json({ error: "请求体必须是 JSON" }, 400); }
  const user = String(body.user || ""), pass = String(body.pass || "");
  const ok = user === LOGIN_CFG.USER && pass.length > 0 && (await sha256Hex(LOGIN_CFG.SALT + pass)) === LOGIN_CFG.PASS_SHA256;
  if (!ok) return json({ error: "账号或密码错误" }, 401);
  const nowISO = new Date().toISOString();
  const expISO = new Date(Date.now() + 7 * 86400e3).toISOString();
  const token = newToken();
  await db.prepare("DELETE FROM sessions WHERE expires_at < ?").bind(nowISO).run();
  await db.prepare("INSERT INTO sessions (token, created_at, expires_at) VALUES (?, ?, ?)").bind(token, nowISO, expISO).run();
  return json({ token, user: LOGIN_CFG.USER, expiresAt: expISO });
}

/* ---- 工作台数据（配置 + 待办，存 D1 state 表） ---- */
async function getState(db) {
  const row = await db.prepare("SELECT value, updated_at FROM state WHERE key = 'main'").first();
  if (!row) return json({ empty: true });
  return new Response(row.value, { headers: { ...JSONH, "cache-control": "no-store", "x-updated-at": row.updated_at } });
}
async function putState(request, db) {
  let body;
  try { body = await request.json(); } catch (e) { return json({ error: "请求体必须是 JSON" }, 400); }
  if (!body || !body.config || !Array.isArray(body.config.services)) return json({ error: "缺少 config 字段" }, 400);
  const now = new Date().toISOString();
  const todos = Array.isArray(body.todos) ? body.todos : [];
  const payload = JSON.stringify({ type: "wb-hub-state", version: 4, config: body.config, todos, savedAt: now });
  await db.prepare("INSERT INTO state (key, value, updated_at) VALUES ('main', ?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = excluded.updated_at")
    .bind(payload, now).run();
  /* 同步写 services 表 → 供网关集中调用（Token 存服务端，前端不接触） */
  const stmts = [];
  for (const s of body.config.services) {
    stmts.push(db.prepare(
      "INSERT INTO services (id, name, url, base_url, auth_type, token, header_name, mapping, enabled, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?) " +
      "ON CONFLICT(id) DO UPDATE SET name=excluded.name, url=excluded.url, base_url=excluded.base_url, auth_type=excluded.auth_type, token=excluded.token, header_name=excluded.header_name, mapping=excluded.mapping, enabled=excluded.enabled, updated_at=excluded.updated_at"
    ).bind(
      String(s.id), String(s.name || s.id), String(s.url || ""), String(s.baseUrl || ""),
      String(s.authType || "none"), String(s.token || ""), String(s.headerName || "X-API-Key"),
      JSON.stringify(s.advanced || {}), s.enabled ? 1 : 0, now
    ));
  }
  if (stmts.length) await db.batch(stmts);
  return json({ ok: true, savedAt: now });
}

/* ---- 集中网关：/api/proxy/<服务id>[/<子路径>] → 转发到各服务真实 API ---- */
async function handleProxy(request, db, url) {
  const m = url.pathname.match(/^\/api\/proxy\/([^/]+)(\/.*)?$/);
  if (!m) return json({ error: "not found" }, 404);
  const id = decodeURIComponent(m[1]);
  const sub = m[2] || "";
  const svc = await db.prepare("SELECT * FROM services WHERE id = ?").bind(id).first();
  if (!svc) return json({ error: `服务 "${id}" 不存在` }, 404);
  if (!svc.base_url) return json({ error: `服务 "${id}" 尚未配置 API 地址，请在工作台设置中保存` }, 404);
  let target;
  try { target = new URL(svc.base_url); } catch (e) { return json({ error: "该服务的 API 地址无效" }, 500); }
  if (sub) target.pathname = target.pathname.replace(/\/$/, "") + sub;
  target.search = url.search;
  const headers = {};
  if (svc.auth_type === "bearer" && svc.token) headers["Authorization"] = "Bearer " + svc.token;
  if (svc.auth_type === "header" && svc.token) headers[svc.header_name || "X-API-Key"] = svc.token;
  const init = { method: request.method, headers, signal: timeoutSignal(12000) };
  if (request.method !== "GET" && request.method !== "HEAD") init.body = await request.text();
  try {
    const resp = await fetch(target.toString(), init);
    return new Response(resp.body, {
      status: resp.status,
      headers: { "content-type": resp.headers.get("content-type") || "application/json", "cache-control": "no-store", "x-proxied-by": "service-hub-gateway" }
    });
  } catch (e) {
    return json({ error: (e.name === "AbortError" ? "上游请求超时（12s）" : e.message) }, 502);
  }
}

/* ---- 连接测试：用表单当前值直接转发（不落库） ---- */
async function handleProxyTest(request) {
  let body;
  try { body = await request.json(); } catch (e) { return json({ error: "请求体必须是 JSON" }, 400); }
  const s = body.service || {};
  if (!s.baseUrl) return json({ error: "缺少 baseUrl" }, 400);
  const headers = {};
  if (s.authType === "bearer" && s.token) headers["Authorization"] = "Bearer " + s.token;
  if (s.authType === "header" && s.token) headers[s.headerName || "X-API-Key"] = s.token;
  try {
    const resp = await fetch(s.baseUrl, { headers, signal: timeoutSignal(12000) });
    const text = await resp.text();
    if (!resp.ok) return json({ error: `目标服务返回 HTTP ${resp.status}`, body: text.slice(0, 500) }, 502);
    try { return json(JSON.parse(text)); } catch (e) { return json({ error: "目标未返回有效 JSON", body: text.slice(0, 500) }); }
  } catch (e) {
    return json({ error: (e.name === "AbortError" ? "请求超时（12s）" : e.message) }, 502);
  }
}

/* ---- 路由入口 ---- */
export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    try {
      if (url.pathname === "/" || url.pathname === "/index.html") {
        return new Response(HTML, { headers: { "content-type": "text/html;charset=UTF-8", "cache-control": "public, max-age=300", "x-content-type-options": "nosniff", "referrer-policy": "no-referrer", "x-frame-options": "SAMEORIGIN" } });
      }
      if (!url.pathname.startsWith("/api/")) return json({ error: "not found" }, 404);
      if (!env.DB) {
        if (url.pathname === "/api/health") return json({ ok: true, mode: "no-db" });
        return json({ error: "D1 数据库未绑定：Workers → Settings → Bindings 添加 D1 绑定，变量名 DB" }, 503);
      }
      await ensureSchema(env.DB);
      if (url.pathname === "/api/health") return json({ ok: true, mode: "server", time: new Date().toISOString() });
      if (url.pathname === "/api/auth/login" && request.method === "POST") return handleLogin(request, env.DB);

      const user = await getUser(request, env.DB);
      if (!user) return json({ error: "unauthorized" }, 401);

      if (url.pathname === "/api/auth/me") return json({ user });
      if (url.pathname === "/api/auth/logout" && request.method === "POST") {
        const m = (request.headers.get("Authorization") || "").match(/^Bearer (.+)$/);
        if (m) await env.DB.prepare("DELETE FROM sessions WHERE token = ?").bind(m[1]).run();
        return json({ ok: true });
      }
      if (url.pathname === "/api/state" && request.method === "GET") return getState(env.DB);
      if (url.pathname === "/api/state" && request.method === "PUT") return putState(request, env.DB);
      if (url.pathname === "/api/proxy-test" && request.method === "POST") return handleProxyTest(request);
      if (url.pathname.startsWith("/api/proxy/")) return handleProxy(request, env.DB, url);
      return json({ error: "not found" }, 404);
    } catch (e) {
      return json({ error: (e && e.message) || "internal error" }, 500);
    }
  }
};
